const $=s=>document.querySelector(s);
const state={replyTo:null,instructions:{guides:[],acknowledged:[]},user:null,workspaceMode:'personal',workspaceRevision:0,users:[],statuses:null,view:'dashboard',tasks:[],office:[],activities:[],summary:null,day:new Date().toLocaleDateString('en-CA'),detail:null,detailTab:'timeline',filter:'',devFilter:'all',qaFilter:'all',typeFilter:'all',dailyEmail:'',workKindFilter:'all',planningFilter:'all',categoryFilter:'all',privateSearch:'',privateStatus:'Active work',privateItems:[],privateAttachments:[],privateDetail:null,privateDetailData:null,archivedTasks:[],boardScope:'active',boardSort:'priority',boardFiltersOpen:false,boardLayout:'cards',boardPhase:'all',boardPeople:'all',local:false};
const escapeHTML=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
// Localize only system-authored copy. User content always uses e(), never ui().
function tr(text,values={}){return globalThis.WorkTrackerLanguage?.translate(text,values)??String(text??'').replace(/\{(\w+)\}/g,(all,key)=>values[key]??all);}
function systemText(node,text,values={}){if(!node)return;if(node.dataset){node.dataset.ui=text;node.dataset.uiValues=JSON.stringify(values);}node.textContent=tr(text,values);}
function ui(text,values={}){return globalThis.WorkTrackerLanguage?.html(text,values)??e(String(text??'').replace(/\{(\w+)\}/g,(all,key)=>values[key]??all));}
const activeTaskDue=t=>t.current_due_date===undefined?t.estimated_delivery_date:t.current_due_date;
const dateFmt=x=>x?new Date(x+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'—';
const cardDate=x=>x?new Date(x+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',...(x.slice(0,4)!==state.day.slice(0,4)?{year:'numeric'}:{}),timeZone:'UTC'}):'—';
const timeFmt=x=>x?new Date(x).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const initial=s=>(s||'?').split(/[@ ._-]/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const who=email=>state.users.find(u=>u.email===email)?.display_name||email?.split('@')[0]||'—';
function avatarContents(email){const person=email===state.user?.email?state.user:(state.users||[]).find(u=>u.email===email);return person?.avatar_id?`<img data-avatar-image src="/api/avatars/${e(person.avatar_id)}" alt="">`:e(initial(who(email)));}
function avatarHtml(email,className='mini-avatar'){return `<span class="${e(className)}" data-avatar-email="${e(email)}">${avatarContents(email)}</span>`;}
function updateProfileAvatars(){for(const node of document.querySelectorAll('[data-avatar-email]'))node.innerHTML=avatarContents(node.dataset.avatarEmail);const profile=$('#avatar');if(profile){profile.dataset.avatarEmail=state.user?.email||'';profile.innerHTML=state.user?avatarContents(state.user.email):'';}const menu=$('#account-menu');if(menu)menu.innerHTML=state.user?`<span class="account-avatar">${avatarContents(state.user.email)}</span><span class="account-caption"><strong>${e(state.user.display_name||who(state.user.email))}</strong><small>${e([...(state.user.role==='admin'?['Admin']:[]),...(state.user.groups||[]).map(g=>g==='Management'?'Manager':g)].join(' · '))}</small></span>`:'Account';}
document.addEventListener('error',ev=>{if(ev.target.matches?.('[data-avatar-image]')){const parent=ev.target.parentElement;parent.textContent=initial(who(parent.dataset.avatarEmail));}},true);
const role=()=>state.user?.role||'';
const canDev=()=>(role()==='admin'&&!isBoss())||(canWrite()&&state.user?.groups?.includes('Engineering'));
const canWrite=()=>!!state.user&&!isBoss();
const hasManagement=()=>!!state.user?.groups?.includes('Management');
const hasPersonalWorkGroups=()=>!!state.user?.groups?.some(g=>g!=='Management');
const hasDualWorkspace=()=>hasManagement()&&hasPersonalWorkGroups();
const isBoss=()=>hasManagement()&&(!hasPersonalWorkGroups()||state.workspaceMode==='team');
const canManage=()=>role()==='admin'&&!isBoss();
const canQA=()=>(role()==='admin'&&!isBoss())||(canWrite()&&state.user?.groups?.includes('QA'));
const api=async(path,options={})=>{
  const headers={'x-workspace-mode':state.workspaceMode,...(options.headers||{})};if(options.body&&!((options.body) instanceof FormData))headers['content-type']='application/json';
  if(options.method&&options.method!=='GET')headers['x-work-tracker']='1';
  if(state.local)headers['x-dev-user']=$('#demo-user').value||'admin@demo.local';
  const r=await fetch('/api'+path,{...options,headers});const contentType=r.headers.get('content-type')||'';
  const d=contentType.includes('json')?await r.json():{error:await r.text()};if(!r.ok)throw Object.assign(new Error(tr(d.error||'Request failed')),{status:r.status});return d;
};
const showToast=(msg,failed=false)=>{const t=$('#toast');t.textContent=tr(msg);t.style.background=failed?'#904949':'#2e3a45';t.classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.add('hidden'),3100)};
const busy=async fn=>{try{await fn();}catch(err){showToast(err.message||String(err),true);console.error(err)}};
const option=(items,sel)=>items.map(v=>`<option value="${e(v)}" ${String(sel)===String(v)?'selected':''}>${e(v)}</option>`).join('');
const badge=(v)=>{const x=String(v||'—');if(['Urgent','High','Medium','Low'].includes(x)){const c=x==='Low'?'green':x==='Medium'?'amber':'red';return `<span class="priority-indicator priority-${c}" aria-label="${e(x)} priority"><span class="priority-dot" aria-hidden="true"></span>${e(x)}</span>`;}let c='gray';if(/Changes Required|Needs Details|Unable|Blocked|Stale|Overdue|Cannot Complete|Needs changes|No Visible|Failed|Error|Rejected/i.test(x))c='red';else if(/Waiting|Need Explanation|Retest|On Hold|Update needed|Partially Passed|Review|Ready|Stage|PR Submitted|Testing|Progress|Merged|At Risk|Reminder|Active|Development|Engineering|Awaiting|Pending|Clarification|To Do/i.test(x))c='amber';else if(/Passed|Completed|Production|Closed|Approved|Resolved|Confirmed/i.test(x))c='green';return `<span class="badge ${c}">${e(x)}</span>`};
const workspaceDayLabel=()=>new Date(state.day+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:'UTC'});
const heading=(eyebrow,title,sub,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1 class="page-title">${e(title)}</h1><div class="subtitle">${ui(sub)}</div></div><div class="heading-actions">${actions}</div></div>${instructionFor(state.view)}`;
function categoryTag(value){
 const name=value||'General';let hash=0;for(const char of name.toLowerCase())hash=(hash*31+char.codePointAt(0))>>>0;
 const tone=({general:2,reports:3,billing:0,scheduling:1,patients:4,other:5})[name.toLowerCase()]??hash%6;
 return `<span class="category-tag category-tone-${tone}" title="${e(name)}">${e(name)}</span>`;
}
function categoryPicker(value,{id='',key='',enabled=true,filter=false}={}){
 const categories=[...new Set([...(state.statuses.categories||[]),...state.tasks.map(t=>t.category),...state.archivedTasks.map(t=>t.category),...(!filter?[value]:[])])].filter(Boolean);
 return `<div class="field category-field"><label ${id?`for="${e(id)}"`:''}>Category</label><select ${id?`id="${e(id)}"`:''} ${key?`class="task-field" data-key="${e(key)}"`:''} data-category-picker data-category-current="${e(value)}" ${enabled?'':'disabled'}>${filter?'<option value="all">Any category</option>':''}${option(categories,value)}${enabled&&canWrite()?'<option value="__add_category__">+ Add category</option>':''}</select><div class="category-create" hidden><input autocomplete="off" type="text" maxlength="80" aria-label="New category name" placeholder="${e(tr('e.g. Inventory'))}" data-ui-placeholder="e.g. Inventory"><div class="category-create-actions"><button type="button" class="btn tiny" data-add-category>Add category</button><button type="button" class="btn tiny" data-cancel-category>Cancel</button></div><p class="category-error" role="alert"></p></div></div>`;
}
document.addEventListener('change',ev=>{
 if(!ev.target.matches('[data-category-picker]'))return;
 if(ev.target.value==='__add_category__'){
  ev.stopImmediatePropagation();ev.target.value=ev.target.dataset.categoryCurrent;
  const form=ev.target.closest('.category-field').querySelector('.category-create');form.hidden=false;form.querySelector('input').focus();
 }else ev.target.dataset.categoryCurrent=ev.target.value;
},true);
document.addEventListener('click',ev=>{
 const button=ev.target.closest('[data-add-category],[data-cancel-category]');if(!button)return;
 const field=button.closest('.category-field'),form=field.querySelector('.category-create'),select=field.querySelector('[data-category-picker]');
 if(button.hasAttribute('data-cancel-category')){form.hidden=true;form.querySelector('.category-error').textContent='';select.focus();return;}
 if(button.disabled)return;button.disabled=true;
 busy(async()=>{try{
  const result=await api('/categories',{method:'POST',body:JSON.stringify({name:form.querySelector('input').value})});state.statuses.categories=result.categories;
  for(const picker of document.querySelectorAll('[data-category-picker]'))if(![...picker.options].some(o=>o.value===result.name))picker.add(new Option(result.name,result.name),picker.querySelector('[value="__add_category__"]'));
  select.value=result.name;select.dataset.categoryCurrent=result.name;form.hidden=true;form.querySelector('input').value='';form.querySelector('.category-error').textContent='';
  clearSuggestedValue(select);select.dispatchEvent(new Event('change',{bubbles:true}));showToast('Category added');
 }catch(err){systemText(form.querySelector('.category-error'),err.message);form.querySelector('input').focus();}finally{button.disabled=false;}});
});
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.matches('.category-create input')){ev.preventDefault();ev.target.closest('.category-create').querySelector('[data-add-category]').click();}});
const empty=(title,sub)=>`<div class="empty"><strong>${ui(title)}</strong>${ui(sub)}</div>`;
function instructionCard(g,review=false){
 const acknowledged=state.instructions.acknowledged.includes(g.id);
 return `<aside class="instruction-card" data-instruction-card="${e(g.id)}" ${review?'data-guide-review':''} aria-label="${e(tr(g.title))} instructions"><div class="instruction-header"><span class="instruction-icon" aria-hidden="true">i</span><h3>${ui(g.title)}</h3>${review&&acknowledged?'<span class="muted-note">Reviewed</span>':''}</div><ol>${g.steps.map(s=>`<li>${ui(s)}</li>`).join('')}</ol>${!acknowledged?`<div class="instruction-footer"><span class="muted-note">${ui("Stays here until you confirm you’ve read it.")}</span><button type="button" class="btn" data-ack-instruction="${e(g.id)}">I understand</button></div>`:''}</aside>`;
}
function instructionFor(surface){return state.instructions.guides.filter(g=>g.surface===surface&&(!g.workspace||g.workspace===state.workspaceMode)&&!state.instructions.acknowledged.includes(g.id)).map(g=>instructionCard(g)).join('');}
function commentReplyLink(c,d){const parent=d.comments.find(p=>p.id===c.reply_to);return parent?`<div class="comment-parent"><strong>Reply to ${e(who(parent.actor_email))}</strong><span>${e(parent.body.slice(0,180))}</span></div>`:'';}
function startCommentReply(cid,focus=true){
 const c=state.detailData?.comments.find(c=>c.id===cid),composer=$('#comment-composer');if(!c||!composer||state.detailData.task.archived||!canWrite())return;
 state.replyTo=cid;const context=$('#comment-reply-context');context.hidden=false;context.innerHTML=`<div><strong>Reply to ${e(who(c.actor_email))}</strong><p>${e(c.body.slice(0,240))}</p></div><button type="button" class="account-link" data-cancel-comment-reply>Cancel reply</button>`;
 const highlighted=[...document.querySelectorAll('[data-highlight-comment]')].find(el=>el.dataset.highlightComment===cid);
 if(highlighted)highlighted.append(composer);else{$('#task-discussion').open=true;$('#discussion-compose-anchor').append(composer);}
 $('#add-comment').textContent='Post reply';
 if(focus){composer.scrollIntoView({block:'nearest',behavior:'smooth'});$('#comment-body').focus({preventScroll:true});}
}
document.addEventListener('click',ev=>{
 const reply=ev.target.closest('[data-reply-comment]');if(reply)return startCommentReply(reply.dataset.replyComment);
 if(ev.target.closest('[data-cancel-comment-reply]')){state.replyTo=null;$('#comment-reply-context').hidden=true;$('#discussion-compose-anchor').append($('#comment-composer'));$('#task-discussion').open=true;$('#add-comment').textContent='Post comment';}
});
function projectTaskList(children,writable,projectId){
 const tasks=children.slice().sort((a,b)=>Number(!!a.archived)-Number(!!b.archived)||Number(a.status==='Completed')-Number(b.status==='Completed')||a.title.localeCompare(b.title));
 return `<section class="project-task-list" aria-label="Related tasks"><div class="project-tasks-heading"><div><h3 class="card-title">Related tasks</h3><p class="muted-note">${ui("Open a task to view its details or log work.")}</p></div>${writable?`<button class="btn" data-private-child="${e(projectId)}">+ Task</button>`:''}</div>${tasks.length?`<div class="project-task-columns"><span>TASK</span><span>STATUS</span></div>${tasks.map(t=>`<button type="button" class="project-task-row" data-private-open="${e(t.id)}" aria-label="Open ${e(t.title)}"><span class="project-task-copy"><strong>${e(t.title)}</strong>${t.description?`<small>${e(t.description)}</small>`:''}</span><span class="project-task-state">${badge(t.archived?'Archived':t.status)}<span aria-hidden="true">›</span></span></button>`).join('')}`:`<p class="project-task-empty muted-note">${ui("No tasks yet. Add a task to break this project into smaller pieces of work.")}</p>`}</section>`;
}
function usageGuide(){
 if(!state.user)return;
 const guides=state.instructions.guides.filter(g=>!g.workspace||g.workspace===state.workspaceMode),current=state.privateDetail?(state.privateDetailData.item.kind==='Project'?'private-project':'private-task'):state.detail?(state.detailData?.task.work_kind==='PM Task'?'pm-task':'engineering-task'):state.view;
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>Usage guide</h2><button class="close" data-close="modal" aria-label="Close guide">×</button></div><p class="muted-note">${ui("Instructions for your work groups. Read any guide again here. Each confirmation is saved only for your account.")}</p>${guides.slice().sort((a,b)=>Number(b.surface===current)-Number(a.surface===current)).map(g=>`<details class="guide-section" ${g.surface===current?'open':''}><summary>${ui(g.title)} <span class="muted-note" data-guide-status="${e(g.id)}">${state.instructions.acknowledged.includes(g.id)?'Reviewed':'New'}</span></summary>${instructionCard(g,true)}</details>`).join('')}`;
 $('#modal-shade').classList.remove('hidden');
}
document.addEventListener('click',ev=>{
 const b=ev.target.closest('[data-ack-instruction]');if(!b||b.disabled)return;
 b.disabled=true;busy(async()=>{try{
  const gid=b.dataset.ackInstruction;await api('/instructions/ack',{method:'POST',body:JSON.stringify({id:gid})});
  if(!state.instructions.acknowledged.includes(gid))state.instructions.acknowledged.push(gid);
  const g=state.instructions.guides.find(g=>g.id===gid);
  for(const card of document.querySelectorAll('[data-instruction-card]'))if(card.dataset.instructionCard===gid){if(card.hasAttribute('data-guide-review'))card.outerHTML=instructionCard(g,true);else card.remove();}
  for(const status of document.querySelectorAll('[data-guide-status]'))if(status.dataset.guideStatus===gid)status.textContent='Reviewed';
 }finally{b.disabled=false;}});
});
const taskTitle=t=>`<div class="title-cell" data-open="${e(t.id)}">${e(t.title)}<div class="muted" style="font-weight:400;margin-top:5px;font-size:10px">${e(t.type)}${activeTaskDue(t)?' · '+e(t.current_due_label||'Due')+' '+e(dateFmt(activeTaskDue(t))):''}${t.parent_task_id?' · '+e(state.tasks.find(p=>p.id===t.parent_task_id)?.title||'Parent task'):''}</div></div>`;
function setView(v,discard=false){if((state.detail||state.privateDetail)&&!discard&&hasDirtyTask())return askDiscardTask(()=>{closeDetail(true);setView(v,true)});if(state.detail||state.privateDetail)closeDetail(true);if(v==='mywork')v='daily';if(v==='engineering')v='board';if(v==='history'&&!canManage())return;state.view=v;$('#crumb').textContent={dashboard:isBoss()?'Team overview':'Dashboard',board:'Engineering Board',daily:isBoss()?'Team activity':'Daily Work',engineering:'Engineering Daily Activity',mywork:'My Work',history:'Activity History',releases:'Version Control',team:'Team Access'}[v]||v;document.querySelectorAll('#nav [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===v));render()}
async function load(){
  const me=await api('/me');state.user=me.user;globalThis.WorkTrackerLanguage?.configure(state.user);state.workspaceMode='personal';state.boardPeople='all';state.workspaceRevision++;state.instructions=me.instructions;state.statuses=me.statuses;state.local=me.devMode;if(state.local)$('#demo-user').value=state.user.email;if(canDev())await api('/releases/ensure',{method:'POST'});
  const [users,tasks,office,activities,summary]=await Promise.all([api('/users'),api('/tasks'),api('/office'),(canManage()?api('/activity'):Promise.resolve({activities:[]})),api('/summary?date='+state.day)]);
  state.users=users.users;state.tasks=tasks.tasks;state.office=office.logs;state.activities=activities.activities;state.summary=summary;
  $('#account-profile').hidden=false;$('#login-entry').hidden=true;$('#nav').hidden=false;$('.top-actions').hidden=false;$('#current-user').textContent=state.user.display_name||who(state.user.email);$('#current-role').textContent=(state.user.groups||[]).map(g=>g==='Management'?'Manager':g).join(', ');updateProfileAvatars();$('#team-nav').hidden=!canManage();$('#admin-nav').hidden=!canManage();
  $('#demo-user').hidden=!state.local;$('#history-nav').hidden=!canManage();
  if(state.local)$('#demo-user').value=state.user.email;
  render();
}
async function reload(){const revision=state.workspaceRevision;const [users,tasks,office,activities,summary,me]=await Promise.all([api('/users'),api('/tasks'),api('/office'),(canManage()?api('/activity'):Promise.resolve({activities:[]})),api('/summary?date='+state.day),api('/me')]);if(revision!==state.workspaceRevision)return;state.user=me.user;state.instructions=me.instructions;state.statuses=me.statuses;globalThis.WorkTrackerLanguage?.configure(state.user);state.users=users.users;state.tasks=tasks.tasks;state.office=office.logs;state.activities=activities.activities;state.summary=summary;render();if(state.detail)await openDetail(state.detail);else if(state.privateDetail)await refreshPrivateDetail()}
let workspaceSwitchBusy=false;
function updateWorkspaceChrome(){
 updateProfileAvatars();
 const wrap=$('#workspace-switch');if(wrap){wrap.hidden=!hasDualWorkspace();for(const button of wrap.querySelectorAll('[data-workspace-mode]')){const active=button.dataset.workspaceMode===state.workspaceMode;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));button.disabled=workspaceSwitchBusy;}}
 const dailyNav=$('#nav [data-view="daily"] .nav-text'),homeNav=$('#nav [data-view="dashboard"] .nav-text');if(dailyNav)dailyNav.textContent=isBoss()?'Team activity':'Daily Work';if(homeNav)homeNav.textContent=isBoss()?'Team overview':'Dashboard';
 for(const [view,label,mobile]of [['daily',isBoss()?'Team activity':'Daily Work',isBoss()?'Team activity':'Daily Work'],['dashboard',isBoss()?'Team overview':'Dashboard',isBoss()?'Overview':'Home']]){const button=$('#nav [data-view="'+view+'"]');if(button){button.setAttribute('aria-label',label);button.title=label;button.dataset.mobileLabel=mobile;}}
 $('#team-nav').hidden=!canManage();$('#history-nav').hidden=!canManage();$('#admin-nav').hidden=!canManage();
}
async function setWorkspaceMode(mode,discard=false){
 if(!hasDualWorkspace()||workspaceSwitchBusy||!['personal','team'].includes(mode)||mode===state.workspaceMode)return;
 if(!discard&&hasDirtyTask())return askDiscardTask(()=>busy(()=>setWorkspaceMode(mode,true)));
 closeDetail(true);workspaceSwitchBusy=true;state.workspaceMode=mode;state.boardPeople='all';state.workspaceRevision++;state.view='dashboard';state.dailyEmail='';state.privateItems=[];state.privateAttachments=[];state.office=[];state.summary=null;state.activities=[];state.instructions.acknowledged=state.instructions.acknowledged||[];
 document.querySelectorAll('#nav [data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view==='dashboard'));$('#crumb').textContent=mode==='team'?'Team overview':'Dashboard';
 $('#content').innerHTML='<div class="loading">Loading '+(mode==='team'?'team overview':'your work')+'…</div>';updateWorkspaceChrome();
 try{await reload();}finally{workspaceSwitchBusy=false;updateWorkspaceChrome();}
}
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-workspace-mode]');if(button)busy(()=>setWorkspaceMode(button.dataset.workspaceMode));});
function labelMobileTables(root){
 for(const table of root.matches?.('table')?[root]:root.querySelectorAll('table')){
  if(!table.closest('.engineering-board,.private-work-board,.private-projects,.next-actions,.priority-today,#daily-results'))continue;
  table.classList.add('mobile-card-table');
  const labels=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());
  for(const row of table.querySelectorAll('tbody tr'))[...row.children].forEach((cell,n)=>{if(cell.colSpan===1)cell.dataset.label=labels[n]||'';});
 }
}
function render(){if(!state.user)return;updateWorkspaceChrome();const el=$('#content');if(state.view==='dashboard'){if(isBoss()){el.innerHTML=heading('TEAM OVERVIEW','Manager overview','Daily work, engineering progress and upcoming releases.',`<input autocomplete="off" class="date-input" type="date" value="${state.day}" data-day>`)+`<div id="manager-results">${ui("Loading team overview…")}</div>`;busy(loadManagerOverview)}else el.innerHTML=renderDashboard();}if(state.view==='board'){el.innerHTML=renderBoard();busy(loadBoardActivity);if(state.boardScope==='archived')busy(loadArchivedTasks);}if(['daily','mywork','engineering'].includes(state.view))el.innerHTML=renderDaily();if(state.view==='history')el.innerHTML=renderHistory();if(state.view==='team')el.innerHTML=renderTeam();if(state.view==='releases'){el.innerHTML=heading(workspaceDayLabel(),'Version Control','Upcoming plans and delivered changes.',canDev()?'<button type="button" class="btn" id="plan-version">+ Plan</button>':'')+`<div id="release-results">${ui("Loading versions…")}</div>`;busy(loadReleases)}el.innerHTML=instructionFor('workspace')+el.innerHTML;labelMobileTables(el);}
function renderDashboard(){
 const s=state.summary||{counts:{total:0,needQa:0,needEngineering:0,production:0},today_activity:[]},cs=s.counts;
 const activity=(s.today_activity||[]).map(a=>`<article class="task-row workspace-update" ${a.task_id?`data-row-activity="${e(a.activity_id)}" data-activity-task="${e(a.task_id)}"`:a.id?`data-row-office="${e(a.id)}"`:''} tabindex="0" role="button" aria-label="Open ${e(a.title)}"><div class="workspace-update-top"><span class="row-flex">${avatarHtml(a.person)}${e(who(a.person))}</span></div>${a.task_id?`<div class="title-cell">${e(a.title)}</div>`:`<strong class="workspace-update-title">${e(a.title)}</strong>`}<p class="workspace-update-note">${e(a.notes||'')}</p><div class="workspace-tag-row">${a.private?badge('Private work'):badge(a.category)}${!a.private&&a.result?badge(a.result):''}</div></article>`).join('');
 return heading(workspaceDayLabel(),'Dashboard','What needs your attention, and what moved forward.',`<input autocomplete="off" class="date-input" type="date" value="${state.day}" data-day>${canWrite()?'<button class="btn primary" data-modal="office">+ Activity</button>':''}`)+
 `<div class="workspace-summary" aria-label="Engineering summary"><div><span class="workspace-summary-number">${cs.total}</span><span>Active tasks</span></div><div><span class="workspace-summary-number">${cs.needQa}</span><span>Waiting for QA</span></div><div><span class="workspace-summary-number">${cs.needEngineering}</span><span>Needs engineering</span></div><div><span class="workspace-summary-number">${cs.production}</span><span>On Production</span></div></div><div class="workspace-home-grid"><div>${renderNextActions(s)}${dashboardTracking(s)}${renderPersonalReminders(s.personal_reminders||[])}</div><section class="workspace-activity"><div class="workspace-section-head"><h2 class="card-title">Today’s activity</h2><button class="account-link" data-view="daily">View all ↗</button></div><div class="workspace-activity-list">${activity||empty('No activity logged yet','New activity and office entries appear here automatically.')}</div></section></div><div class="workspace-home-footer">${canManage()?'<button class="btn tiny" id="download-export">Export permitted data</button>':''}<span class="muted-note">${ui('Open an Engineering task to carry out its next step. Open Daily Work tasks to record personal progress.')}</span></div>`;
}

function isNextActionRelevant(t){return t.planning_status==='Active'&&t.workflow.owner===state.user.email;}
function renderNextActions(s){
 const items=[...new Map((s.next_actions||[]).map(t=>[t.id,t])).values()].filter(t=>!['archived'].includes(t.workflow.phase)&&t.development_status!=='Closed'&&isNextActionRelevant(t)).sort((a,b)=>priorityRank(a.priority)-priorityRank(b.priority)||Number(a.workflow.owner!==state.user.email)-Number(b.workflow.owner!==state.user.email)||a.sort_order-b.sort_order).slice(0,8);
 const rows=items.map(t=>{const g=t.workflow,feedback=g.phase==='development'&&['Changes Required','Partially Passed','Need Explanation','No Visible Changes','Unable to Test'].includes(t.qa_status);const reason=g.phase==='pm'?t.pm_stage:feedback?'Needs changes':g.phase==='qa'?(t.qa_status==='Retest Required'?'Retest required':'Ready for QA'):g.phase==='production'?'Ready for Production':g.phase==='review'?(t.feasibility==='Needs Clarification'?'Needs clarification':t.feasibility==='Cannot Complete'?'Scope needs revision':'Engineer review'):'In progress';const action=g.phase==='review'?'Review scope and delivery date':g.phase==='qa'?'Test the confirmed Stage build':g.phase==='production'?'Deploy and verify Production':feedback?'Fix QA feedback, then merge to Stage':'Continue development, then merge to Stage';return `<div class="task-row next-action-card ${feedback?'next-action-attention':''}" data-row-task="${e(t.id)}" tabindex="0" role="button" aria-label="Open ${e(t.title)}"><div class="workspace-tag-row">${categoryTag(t.category)}<span title="${e(feedback?t.qa_status:reason)}">${badge(reason)}</span><span class="card-priority">${badge(t.priority)}</span></div><strong class="workspace-task-title">${e(t.title)}</strong><p class="workspace-next-action" title="${e(g.instruction)}">↳ ${ui(g.instruction)}</p><div class="workspace-task-footer"><span class="row-flex" title="${e(g.role)} · Next action owner">${avatarHtml(g.owner)}${e(g.owner?who(g.owner):'Choose owner')}</span><span>${activeTaskDue(t)?e(t.current_due_label||'Due')+' '+e(cardDate(activeTaskDue(t))):''}</span></div></div>`;}).join('');
 if(!items.length)return `<section class="dashboard-queue next-actions-empty" aria-label="Needs My Action"><div class="queue-heading"><h2>Needs My Action</h2><span class="queue-count" aria-label="0 items">0</span><button class="account-link" data-view="board">View board ↗</button></div><div class="queue-empty"><strong>${ui('All caught up')}</strong><p>${ui('No tasks currently need an action.')}</p></div></section>`;
 return `<section class="next-actions workspace-next-actions"><div class="workspace-section-head"><h2 class="card-title">Needs My Action <span class="muted-note">${items.length}</span></h2><button class="account-link" data-view="board">View board ↗</button></div><div class="workspace-next-list">${rows||empty('All caught up','No tasks currently need an action.')}</div></section>`;
}
const priorityRank=p=>({Urgent:0,High:1,Medium:2,Low:3})[p]??4;

function boardNextAction(t,includeOwner=true){if(t.planning_status==='Backlog'||t.planning_status==='Planned')return e(t.planning_status);if(t.work_kind==='PM Task'&&t.workflow?.phase==='pm')return e(t.pm_stage)+(includeOwner?' · '+e(who(t.workflow.owner)):'');if(t.work_kind==='Quick Task')return e(t.work_status)+(includeOwner?' · '+e(who(t.assignee)):'');const g=t.workflow;if(!g)return e(t.next_step||'Review task')+(includeOwner?' · '+e(who(t.next_action_owner||t.assignee)):'');const label=g.phase==='review'?(t.feasibility==='Needs Clarification'?'Clarify requirements':t.feasibility==='Cannot Complete'?'Review scope':'Review feasibility'):g.phase==='development'?(t.qa_status!=='Not Tested'?'Fix QA feedback':t.development_status==='Merged / Awaiting Stage'?'Deploy to Stage':'Continue development'):g.phase==='qa'?'Test on Stage':g.phase==='production'?'Confirm Production':g.phase==='done'?(t.development_status==='Closed'?'Completed':'Confirm completion'):'Restore task';return ui(label)+(includeOwner&&g.owner?' · '+e(who(g.owner)):'');}
const boardFilterFields=[['workKindFilter','Work type'],['planningFilter','Planning status'],['categoryFilter','Category'],['devFilter','Development'],['qaFilter','QA progress']];
const boardPhaseLabels={all:'All tasks',engineering:'Engineering',qa:'Ready for QA',production:'Production'};
function boardFilterEntries(){return [...(state.filter.trim()?[{key:'filter',label:'Search',value:state.filter.trim()}]:[]),...boardFilterFields.filter(([key])=>state[key]&&state[key]!=='all').map(([key,label])=>({key,label,value:key==='qaFilter'?({ready:'Ready to test',changes:'Needs changes',passed:'Passed',blocked:'Blocked'})[state[key]]:state[key]}))];}
function clearBoardFilters(key){if(key==='all'){state.filter='';state.boardPhase='all';state.boardPeople='all';for(const [field]of boardFilterFields)state[field]='all';}else if(key==='filter')state.filter='';else if(key==='boardPhase')state.boardPhase='all';else if(boardFilterFields.some(([field])=>field===key))state[key]='all';}
function matchesBoardQA(t){if(state.qaFilter==='all')return true;if(state.qaFilter==='ready')return t.workflow?.phase==='qa';if(state.qaFilter==='changes')return ['Changes Required','Partially Passed','Need Explanation'].includes(t.qa_status);if(state.qaFilter==='passed')return t.qa_status==='Passed';if(state.qaFilter==='blocked')return ['Unable to Test','No Visible Changes'].includes(t.qa_status);return false;}
function matchesBoardPhase(t,phase=state.boardPhase||'all'){return phase==='all'||(phase==='engineering'?['review','development'].includes(t.workflow?.phase):phase==='qa'?t.workflow?.phase==='qa':phase==='production'?['production','done'].includes(t.workflow?.phase):false);}
const boardPeopleLabels={all:'All team',related:'Related to me',action:'Needs my action',unassigned:'Unassigned'};
function matchesBoardPerson(t){const view=state.boardPeople||'all',me=state.user?.email;if(view==='all')return true;if(view==='unassigned')return !t.assignee&&!t.archived&&t.development_status!=='Closed';if(!me)return false;if(view==='related')return [t.assignee,t.qa_owner,t.next_action_owner,t.workflow?.owner,t.created_by,t.pm_owner].includes(me);if(view==='action')return !t.archived&&t.development_status!=='Closed'&&t.workflow?.owner===me&&(t.workflow.phase==='pm'||t.workflow.actions===undefined||t.workflow.actions.length>0);return false;}
function boardScopeTasks(){return state.boardScope==='archived'?state.archivedTasks:state.tasks.filter(t=>!t.archived&&(state.boardScope==='completed'?t.development_status==='Closed':t.development_status!=='Closed'));}
function boardEmptyState(source){return source.length?empty('No matching tasks','Try another search or clear the filters.'):state.boardScope==='archived'?empty('No archived tasks','Archived tasks will appear here.'):state.boardScope==='completed'?empty('No completed tasks','Tasks appear here after Confirm task complete.'):state.tasks.length?empty('No active tasks','Completed tasks are in Completed. Stored tasks are in Archived.'):empty('No tasks yet','Use + New to add your first task.');}
function filterBoardTasks(tasks,{ignorePhase=false}={}){const q=state.filter.trim().toLowerCase();return tasks.filter(t=>(!q||[t.title,t.description,t.project,t.category,state.tasks.find(p=>p.id===t.parent_task_id)?.title,t.assignee,t.next_action_owner,who(t.assignee),who(t.next_action_owner)].join(' ').toLowerCase().includes(q))&&(state.workKindFilter==='all'||t.work_kind===state.workKindFilter)&&(state.planningFilter==='all'||t.planning_status===state.planningFilter)&&(state.categoryFilter==='all'||t.category===state.categoryFilter)&&(state.devFilter==='all'||t.development_status===state.devFilter)&&matchesBoardQA(t)&&matchesBoardPerson(t)&&(ignorePhase||matchesBoardPhase(t)));}
function renderBoardPhaseTabs(source){const base=filterBoardTasks(source,{ignorePhase:true});return `<div class="board-phase-tabs" role="group" aria-label="Workflow stage">${Object.entries(boardPhaseLabels).map(([value,label])=>`<button type="button" data-board-phase="${value}" class="${(state.boardPhase||'all')===value?'selected':''}" aria-pressed="${(state.boardPhase||'all')===value}">${label}<span>${base.filter(t=>matchesBoardPhase(t,value)).length}</span></button>`).join('')}</div>`;}
function renderBoardFilters(){
 const entries=boardFilterEntries(),count=entries.filter(f=>f.key!=='filter').length;
 const categories=[...new Set([...(state.statuses.categories||[]),...state.tasks.map(t=>t.category),...state.archivedTasks.map(t=>t.category)])].filter(Boolean);
 return `<section class="board-toolbar" aria-label="Search and filter Engineering tasks"><div class="board-toolbar-main"><input autocomplete="off" type="search" class="search" id="task-search" aria-label="Search Engineering tasks" placeholder="${e(tr("Search tasks, projects or people"))}" data-ui-placeholder="Search tasks, projects or people" value="${e(state.filter)}"><select id="board-people" class="select board-people-picker" aria-label="Task view">${Object.entries(boardPeopleLabels).map(([value,label])=>`<option value="${value}" ${(state.boardPeople||'all')===value?'selected':''}>${label}</option>`).join('')}</select><div class="segmented board-scope-tabs" role="group" aria-label="Task scope"><button type="button" data-board-scope="active" class="${state.boardScope==='active'?'selected':''}" aria-pressed="${state.boardScope==='active'}">Active</button><button type="button" data-board-scope="completed" class="${state.boardScope==='completed'?'selected':''}" aria-pressed="${state.boardScope==='completed'}">Completed</button><button type="button" data-board-scope="archived" class="${state.boardScope==='archived'?'selected':''}" aria-pressed="${state.boardScope==='archived'}">Archived</button></div><button type="button" class="btn board-filter-toggle ${count?'has-filters':''}" data-board-filters-toggle aria-expanded="${state.boardFiltersOpen}" aria-controls="board-filter-panel"><svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M3 5h14M3 10h14M3 15h14"/><circle cx="7" cy="5" r="2" fill="white"/><circle cx="13" cy="10" r="2" fill="white"/><circle cx="8" cy="15" r="2" fill="white"/></svg>Filters${count?`<span class="board-filter-count">${count}</span>`:''}</button></div><div id="board-filter-panel" class="board-filter-panel" ${state.boardFiltersOpen?'':'hidden'}><div class="board-filter-fields"><div class="field"><label for="work-kind-filter">Work type</label><select id="work-kind-filter"><option value="all">Any work</option>${option(['Engineering','Quick Task','PM Task'],state.workKindFilter)}</select></div>${categoryPicker(state.categoryFilter,{id:'category-filter',filter:true})}<div class="field board-filter-wide"><label for="dev-filter">Development stage</label><select id="dev-filter"><option value="all">Any stage</option>${option(state.statuses.development,state.devFilter)}</select></div><div class="field board-filter-wide"><label for="board-sort">Sort by</label><select id="board-sort">${option(['Priority first','Manual order','Recently updated'],state.boardSort==='manual'?'Manual order':state.boardSort==='recent'?'Recently updated':'Priority first')}</select></div><div class="field board-filter-wide"><label for="qa-filter">QA progress</label><select id="qa-filter"><option value="all">Any progress</option>${[["ready","Ready to test"],["changes","Needs changes"],["passed","Passed"],["blocked","Blocked"]].map(([value,label])=>`<option value="${value}" ${state.qaFilter===value?"selected":""}>${label}</option>`).join('')}</select></div><div class="field"><label for="planning-filter">Planning status</label><select id="planning-filter"><option value="all">Any planning status</option>${option(['Backlog','Planned','Active','Completed'],state.planningFilter)}</select></div></div><div class="board-filter-footer"><span class="muted-note">${ui("The board updates as you choose.")}</span><button type="button" class="btn tiny" data-board-filters-toggle>Done</button></div></div>${entries.length?`<div class="board-filter-chips" aria-label="Applied filters">${entries.map(f=>`<button type="button" class="board-filter-chip" data-clear-board-filter="${e(f.key)}" aria-label="Remove ${e(f.label)} filter: ${e(f.value)}"><span>${e(f.label)}: ${e(f.value)}</span><span aria-hidden="true">×</span></button>`).join('')}<button type="button" class="account-link" data-clear-board-filter="all">Clear all</button></div>`:''}</section>`;
}
function renderBoardLayout(){return `<div class="workspace-board-view"><div class="segmented" role="group" aria-label="Task layout"><button type="button" data-board-layout="cards" class="${state.boardLayout==='cards'?'selected':''}" aria-pressed="${state.boardLayout==='cards'}">Cards</button><button type="button" data-board-layout="list" class="${state.boardLayout==='list'?'selected':''}" aria-pressed="${state.boardLayout==='list'}">List</button></div></div>`;}
function renderBoard(){
 const source=boardScopeTasks(),matches=filterBoardTasks(source);
 const compare=(a,b)=>(a.development_status==='Closed')-(b.development_status==='Closed')|| (state.boardSort==='manual'?(a.sort_order-b.sort_order||priorityRank(a.priority)-priorityRank(b.priority)):state.boardSort==='recent'?String(b.updated_at).localeCompare(String(a.updated_at)):(priorityRank(a.priority)-priorityRank(b.priority)||a.sort_order-b.sort_order))||a.title.localeCompare(b.title);matches.sort(compare);
 return heading(workspaceDayLabel(),'Engineering Board','Shared tasks, with the next step front and center.',`<div class="board-heading-actions">${renderBoardLayout()}${canWrite()?'<button class="btn primary workspace-create-action" data-modal="task">+ New</button>':''}</div>`)+
 renderBoardFilters()+renderBoardPhaseTabs(source)+
 (state.boardLayout==='cards'?renderEngineeringCards(matches,source):`<section class="card board-card engineering-board"><div class="table-wrap"><table class="table"><thead><tr><th>TASK</th><th>CATEGORY</th><th>PRIORITY</th><th>DEVELOPMENT</th><th>QA RESULT</th><th>ASSIGNED TO</th><th>NEXT ACTION</th><th>LAST ENGINEER</th><th>LAST QA</th></tr></thead><tbody>${matches.map(t=>`<tr class="task-row ${state.detail===t.id?'selected':''}" data-row-task="${e(t.id)}" tabindex="0" role="button" aria-label="Open ${e(t.title)}"><td>${taskTitle(t)}</td><td>${categoryTag(t.category)}</td><td>${badge(t.priority)}</td><td>${badge(t.work_kind==='PM Task'?t.pm_stage:t.work_kind==='Quick Task'?t.work_status:t.development_status)}</td><td>${t.work_kind==='Quick Task'||t.work_kind==='PM Task'&&t.pm_stage!=='Implementation'?'—':badge(t.qa_status)}</td><td>${e(who(t.assignee))}</td><td>${boardNextAction(t)}</td><td>${e(dateFmt(t.last_engineer_action))}</td><td>${e(dateFmt(t.last_qa_action))}</td></tr>`).join('')||`<tr><td colspan="9">${boardEmptyState(source)}</td></tr>`}</tbody></table></div></section>`)+`<div class="footer-note">${matches.length} of ${source.length} ${state.boardScope==='archived'?'archived':state.boardScope==='completed'?'completed':'active'} tasks · ${state.boardSort==='manual'?'Manual order':state.boardSort==='recent'?'Recently updated':'Priority first'}</div><div class="section-gap"></div><section class="card"><div class="card-head"><div><h2 class="card-title">Daily Engineering Activity</h2></div><input autocomplete="off" type="date" class="date-input" value="${state.day}" data-day></div><div id="board-daily-results">${ui("Loading activity…")}</div></section>`;
}
function boardPhaseBadge(t){if(t.planning_status==='Backlog'||t.planning_status==='Planned')return badge(t.planning_status);if(t.work_kind==='PM Task'&&t.workflow?.phase==='pm')return badge(t.pm_stage);if(t.work_kind==='Quick Task')return badge(t.work_status);const phase=t.workflow?.phase;return badge(phase==='qa'?'Ready for QA':phase==='production'?'Ready for Production':phase==='done'?t.development_status==='Closed'?'Completed':'On Production':phase==='archived'?'Archived':['Changes Required','Partially Passed','Need Explanation','No Visible Changes','Unable to Test'].includes(t.qa_status)?'Needs changes':'Engineering');}
function renderEngineeringCards(items,source){
 return `<section class="engineering-board workspace-engineering-cards" aria-label="Engineering tasks">${items.map(t=>{const owner=t.workflow?.owner||t.next_action_owner||t.assignee,ownerLabel=t.workflow?.owner||t.next_action_owner?'Next action owner':'Assignee';return `<div class="task-row workspace-engineering-card ${state.detail===t.id?'selected':''}" data-row-task="${e(t.id)}" tabindex="0" role="button" aria-label="Open ${e(t.title)}"><div class="workspace-tag-row">${categoryTag(t.category)}${boardPhaseBadge(t)}${t.archived&&t.development_status==='Closed'?badge('Completed'):''}<span class="card-priority">${badge(t.priority)}</span></div><strong class="workspace-task-title">${e(t.title)}</strong><p class="workspace-task-meta">${t.work_kind&&t.work_kind!=='Engineering'?e(t.work_kind)+' · '+e(t.work_kind==='PM Task'?t.pm_stage:t.work_status)+(t.pm_stage==='Implementation'?' · '+e(t.development_status)+' · QA: '+e(t.qa_status):''):`${e(t.project&&t.project!=='CRM'?t.project:t.type)} · ${e(t.development_status)} · QA: ${e(t.qa_status)}`} · ${e(t.planning_status)}${t.parent_task_id?' · '+e(state.tasks.find(p=>p.id===t.parent_task_id)?.title||'Parent task'):''}</p><p class="workspace-next-action"><span aria-hidden="true">↳</span> ${boardNextAction(t,false)}</p><div class="workspace-task-footer"><span class="row-flex" title="${ownerLabel}: ${e(who(owner))} · Assignee: ${e(who(t.assignee))}">${avatarHtml(owner)}${e(who(owner))}</span><span class="workspace-priority-date">${t.development_status==='Closed'&&t.completed_date?'Completed '+e(cardDate(t.completed_date)):activeTaskDue(t)?e(t.current_due_label||'Due')+' '+e(cardDate(activeTaskDue(t))):''}</span></div></div>`;}).join('')||boardEmptyState(source)}</section>`;
}
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-board-layout]');if(button){state.boardLayout=button.dataset.boardLayout;render();}});
function renderDaily(){
 return heading(isBoss()?'TEAM OVERVIEW':'PERSONAL WORKSPACE',isBoss()?'Team activity':'Daily Work',isBoss()?'See what everyone worked on each day.':'Your ongoing projects, small tasks and daily activities.',`${canWrite()?'<button class="btn primary workspace-create-action" data-modal="office">+ Activity</button>':''}<input autocomplete="off" type="date" class="date-input" value="${state.day}" data-day>`)+
 (isBoss()?`<div class="filters"><label>Team member</label><select class="select" id="daily-email"><option value="">Everyone</option>${state.users.filter(u=>u.enabled).map(u=>`<option value="${e(u.email)}" ${state.dailyEmail===u.email?'selected':''}>${e(who(u.email))}</option>`).join('')}</select></div>`:'')+
 (isBoss()?'':'<div id="private-work-results"></div><div class="section-gap"></div>')+'<div id="daily-results">Loading activities…</div>';
}
async function loadDaily(){const revision=state.workspaceRevision,day=state.day,email=state.dailyEmail,params=new URLSearchParams({date:day});if(isBoss()&&email)params.set('email',email);const [d,p]=await Promise.all([api('/daily?'+params),isBoss()?Promise.resolve({items:[],attachments:[]}):api('/private-work')]);if(revision!==state.workspaceRevision||state.view!=='daily'||day!==state.day||email!==state.dailyEmail)return;state.privateItems=p.items;state.privateAttachments=p.attachments||[];renderPrivateWork();
 const rows=[...d.activities.map(a=>({dt:a.created_at,person:a.actor_email,kind:a.action_type,title:a.task_title,result:a.result,notes:a.notes,task_id:a.task_id,attachments:(d.attachments||[]).filter(f=>f.activity_id===a.id||(a.comment_id&&f.comment_id===a.comment_id))})),...d.office.map(a=>({id:a.id,dt:a.created_at,person:a.owner_email,kind:'Private activity',title:a.title,result:a.status,notes:a.details,item:a.work_item_id,attachments:(d.attachments||[]).filter(f=>f.office_id===a.id)}))].sort((a,b)=>b.dt.localeCompare(a.dt));const body=$('#daily-results');if(!body)return;
 body.innerHTML=isBoss()?dailyActivitySection(rows,'Team activities · '+dateFmt(day)):dailyActivitySection(rows.filter(r=>r.id),'Daily Work activity · '+dateFmt(day),true,false)+(rows.some(r=>r.task_id)?dailyActivitySection(rows.filter(r=>r.task_id),'Engineering activity · '+dateFmt(day),true):'');
 labelMobileTables(body);
}
function renderHistory(){
 if(!canManage())return empty('Access denied','Activity History is Admin only.');const rows=state.activities;return heading('AUDITABLE RECORDS','Activity History','Append-only work log. Original actions and timestamps are never overwritten.',`<input autocomplete="off" type="search" class="search" id="history-search" placeholder="${e(tr("Filter by task, person or result"))}" data-ui-placeholder="Filter by task, person or result" value="${e(state.filter)}">`)+
 `<section class="card board-card"><div class="table-wrap"><table class="table"><thead><tr><th>WORK DATE</th><th>RECORDED AT</th><th>PERSON</th><th>ACTION</th><th>TASK</th><th>RESULT / NOTES</th></tr></thead><tbody>${rows.filter(a=>!state.filter||[a.task_title,a.actor_email,a.result,a.notes].join(' ').toLowerCase().includes(state.filter.toLowerCase())).map(a=>`<tr><td>${e(dateFmt(a.activity_date))}</td><td>${e(timeFmt(a.created_at))}</td><td>${e(who(a.actor_email))}</td><td>${badge(a.action_type)}</td><td><div class="title-cell" data-open="${e(a.task_id)}">${e(a.task_title)}</div></td><td title="${e(a.notes)}" style="max-width:290px"><strong style="font-size:11px;color:#43515d">${e(a.result)}</strong><div class="muted" style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${e(a.notes)}</div></td></tr>`).join('')||`<tr><td colspan="6">${empty('No history','Activity entries appear here automatically.')}</td></tr>`}</tbody></table></div></section>`;
}
function renderTeam(){if(!canManage())return empty('Access denied','Only Admin can manage members.');return heading('PERMISSIONS','Team Access','Admin manages team accounts. Private daily entries remain visible only to the owner and boss.',`<button class="btn primary" data-modal="user">+ Add member</button>`)+`<div class="report-intro">${ui("Create an email account, assign its system role and work groups, then set its password.")}</div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>ACCOUNT</th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${avatarHtml(u.email)}<b class="focus-num">${e(u.display_name||'—')}</b></td><td>${e(u.email)}</td><td>${badge(u.role)} ${e(JSON.parse(u.groups_json||'[]').map(g=>g==='Management'?'Manager':g).join(' · '))} </td><td>${u.enabled?badge('Active'):badge('Disabled')} <button class="btn" data-edit-user="${e(u.email)}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`;
}
let detailRequest=0;
