 if(old!==taskId){state.replyTo=null;pendingActivityFiles=[];pendingCommentFiles=[];}state.detail=taskId;const request=++detailRequest;$('#panel-shade').classList.remove('hidden');$('#detail-panel').classList.remove('hidden');
