 const d=await api('/tasks/'+taskId);if(request!==detailRequest||state.detail!==taskId)return;
 state.detailTab=old===taskId?tab:'timeline';renderDetail(d);$('#detail-panel').scrollTop=old===taskId?scroll:0;
 document.querySelectorAll('[data-row-task]').forEach(r=>r.classList.toggle('selected',r.dataset.rowTask===taskId));
