function syncWorkflowStage(){const stage=document.querySelector('[data-workflow-field="development_status"]'),handoff=document.querySelector('[data-stage-handoff]'),button=document.querySelector('[data-engineering-confirm]');if(!stage||!handoff||!button)return;const onStage=stage.value==='On Stage';handoff.hidden=!onStage;const qa=handoff.querySelector('[data-workflow-field="qa_owner"]');qa.disabled=!onStage;qa.required=onStage;button.dataset.workflowAction=onStage?'stage':'progress';button.textContent=onStage?'Confirm merged to Stage → QA':'Confirm engineering stage';}
