 if(delivery){delivery.hidden=!confirmed;delivery.querySelector('input').disabled=!confirmed;}
 if(notes){notes.required=!confirmed;const label=notes.closest('.field').querySelector('label');label.textContent=confirmed?'Review notes (optional)':fromPM?'Details / reason for PM *':'Review / clarification notes *';}
