function changeTab(t){state.detailTab=t;renderDetail(state.detailData)}
function privateActivityAssociation(workItem='',preserveCompleted=false){
 const own=state.privateItems.filter(i=>i.owner_email===state.user.email&&!i.archived&&(i.kind!=='Task'||i.status!=='Completed'||(preserveCompleted&&i.id===workItem))),selected=own.find(i=>i.id===workItem),project=selected?.kind==='Project'?selected:own.find(i=>i.id===selected?.parent_id&&i.kind==='Project');
 if(project)return `<div class="field"><label>Project</label><div class="report-intro">${e(project.title)}</div></div><div class="field"><label>Activity belongs to</label><select id="office-item"><option value="${e(project.id)}" ${selected.id===project.id?'selected':''}>Project itself</option>${own.filter(i=>i.kind==='Task'&&i.parent_id===project.id).map(i=>`<option value="${e(i.id)}" ${i.id===workItem?'selected':''}>Task · ${e(i.title)}</option>`).join('')}</select></div>`;
 return `<div class="field"><label>Private project / task (optional)</label><select id="office-item"><option value="">Standalone activity</option>${own.map(i=>`<option value="${e(i.id)}" ${i.id===workItem?'selected':''}>${e(i.kind)} · ${e(i.title)}</option>`).join('')}</select></div>`;
}
async function openPrivateActivity(iid){const d=await api('/private-work');state.privateItems=d.items;const i=state.privateItems.find(i=>i.id===iid);if(!i)throw new Error('This work item is no longer available');modal('office',{workItem:iid,parent:i.kind==='Project'?iid:i.parent_id});}
function markSuggestedDefaults(root,selector){for(const field of root.querySelectorAll(selector)){if(!field.value)continue;field.dataset.suggested='true';field.classList.add('suggested-value');}}
function clearSuggestedValue(field){delete field.dataset.suggested;field.classList.remove('suggested-value');}
for(const event of ['input','change'])document.addEventListener(event,ev=>{if(ev.target.matches('[data-suggested]'))clearSuggestedValue(ev.target);});
function defaultNewWorkKind(user){const groups=user?.groups||[];return groups.includes('Engineering')?'Engineering':groups.includes('PM')?'PM Task':'Engineering';}
function modal(kind,{mode='activity',parent='',workItem='',preserveCompleted=false}={}){if(newTaskSaving)return;if(kind==='task'&&hasDirtyTask())return askDiscardTask(()=>{closeDetail(true);modal(kind,{mode,parent,workItem,preserveCompleted});});editingOfficeId=null;if(kind==='task'){pendingNewTaskFiles=[];savedNewTaskId=null;}if(kind==='office'){pendingDailyFiles={activity:[],task:[]};savedDailyTaskId=null;}let markup='',title='';
 if(kind==='task'){
  title='New task';markup=`<p class="task-create-intro">${ui("Describe the request, choose an engineer, and add the details they need to review it.")}</p><section class="task-create-section"><div class="field"><label for="new-title">Task title *</label><input autocomplete="off" id="new-title" maxlength="160" placeholder="${e(tr("e.g. Fix a login issue"))}" data-ui-placeholder="e.g. Fix a login issue" autofocus></div><div class="field"><label for="new-description">Requirements / reproduction steps</label><textarea autocomplete="off" id="new-description" placeholder="${e(tr("e.g. Users cannot sign in. They should be able to open their account."))}" data-ui-placeholder="e.g. Users cannot sign in. They should be able to open their account."></textarea></div></section><section class="task-create-section"><h3 class="card-title">Task details</h3><div class="task-create-grid"><div class="field"><label>Work type</label><select id="new-work-kind">${option(['Engineering','Quick Task',...(canManage()||state.user.groups.includes('PM')||state.user.groups.includes('Engineering')?['PM Task']:[])],defaultNewWorkKind(state.user))}</select></div><div class="field"><label>Planning status</label><select id="new-planning-status">${option(['Active','Planned','Backlog'],'Active')}</select></div><div class="field" hidden><label>PM work category</label><select id="new-work-category">${option(pmCategories,pmCategories[0])}</select></div></div><div class="task-create-grid">${inputSelect('Type','new-type','New Feature',state.statuses.types)}${inputSelect('Priority','new-priority','Medium',state.statuses.priorities)}${categoryPicker('General',{id:'new-category'})}</div><div class="task-create-grid two"><div class="field"><label for="new-assignee">Assignee</label><select id="new-assignee">${workflowMemberOptions('Engineering')}</select></div><div class="field"><label for="new-parent">Parent task (optional)</label><select id="new-parent"><option value="">No parent task</option>${state.tasks.filter(t=>t.work_kind==='Engineering').map(t=>`<option value="${e(t.id)}">${e(t.title)}</option>`).join('')}</select></div></div><p class="muted-note">${ui("The engineer reviews feasibility first. Confirm merged to Stage and assign QA in the same step.")}</p></section><section class="task-create-section task-create-attachments"><h3 class="card-title">Attachments (optional)</h3>${evidencePicker('new-task-files','new-task','Images & files')}<p class="muted-note">${ui("Add reference images or files now. Each file can be up to 8 MB.")}</p><p id="new-task-upload-error" class="danger-link" role="alert"></p></section>`;
 }else if(kind==='office'){
  title='Add daily work';markup=`<div class="report-intro">${ui("Only you and the manager can view your private work.")}</div><div class="daily-entry-mode" role="group" aria-label="Work type"><button type="button" data-daily-mode="activity" aria-pressed="true">Activity</button><button type="button" data-daily-mode="task" aria-pressed="false">Task</button></div><input autocomplete="off" type="hidden" id="daily-entry-mode" value="activity"><div id="daily-activity-fields"><div class="field"><label>Work title *</label><input autocomplete="off" id="office-title" placeholder="${e(tr("e.g. Update the price list"))}" data-ui-placeholder="e.g. Update the price list"></div><div class="form-row"><div class="field"><label>Work date</label><input autocomplete="off" type="date" id="office-date" value="${state.day}"></div><div class="field"><label>Category</label><select id="office-category">${option(['Work','Meeting','Other'],'Work')}</select></div><input autocomplete="off" type="hidden" id="office-status" value=""></div>${privateActivityAssociation(workItem,preserveCompleted)}<div class="field" id="office-minutes-field"><label>Time spent (minutes, optional)</label><input autocomplete="off" id="office-minutes" type="number" min="0" max="1440"></div><div class="field"><label>Details</label><textarea autocomplete="off" id="office-details" placeholder="${e(tr("e.g. Updated the price list. Waiting for approval."))}" data-ui-placeholder="e.g. Updated the price list. Waiting for approval."></textarea></div><div id="office-recurrence-controls" class="cycle-control" hidden><label class="completion-choice"><input autocomplete="off" type="checkbox" id="office-complete-cycle"><span class="completion-choice-mark" aria-hidden="true">✓</span><span>${ui("Complete this occurrence")}</span></label><p class="muted-note" id="office-cycle-info"></p></div>${completeTaskControl('office')}${evidencePicker('daily-activity-files','daily-activity','Images for this activity')}</div><div id="daily-task-fields" hidden><p class="muted-note">${ui("Add a task for ongoing or already completed work. Log dated progress as activities when you work on it.")}</p><div class="field"><label>Task title *</label><input autocomplete="off" id="daily-task-title" maxlength="180" placeholder="${e(tr("e.g. Prepare the monthly report"))}" data-ui-placeholder="e.g. Prepare the monthly report"></div><div class="field"><label>Project (optional)</label><select id="daily-task-parent"><option value="">Standalone task</option>${state.privateItems.filter(i=>i.kind==='Project'&&!i.archived&&i.owner_email===state.user.email&&(i.status!=='Completed'||i.id===parent)).map(i=>`<option value="${e(i.id)}" ${i.id===parent?'selected':''}>${e(i.title)}</option>`).join('')}</select></div><div class="field"><label for="daily-task-status">Status</label><select id="daily-task-status">${option(['In Progress','Waiting','Completed'],'In Progress')}</select><p class="muted-note">${ui("Choose Completed for finished work. Completed tasks appear under Completed or All work; add a dated activity to record the work you did.")}</p></div><div class="field" id="daily-task-completed-date-field" hidden><label for="daily-task-completed-date">Completed date *</label><input autocomplete="off" id="daily-task-completed-date" type="date" value="${todayDate()}"></div><div class="field"><label>Description</label><textarea autocomplete="off" id="daily-task-description" placeholder="${e(tr("e.g. Check the latest prices and update the price list."))}" data-ui-placeholder="e.g. Check the latest prices and update the price list."></textarea></div>${recurrenceFields('daily-task')}${evidencePicker('daily-task-files','daily-task','Task images')}</div><p id="daily-upload-error" role="alert"></p>`;
 }else if(kind==='user'){
  title='Add or update team member';markup=`<div class="field"><label>Email address (login account)</label><input autocomplete="off" id="user-email" type="email" placeholder="teammate@example.com"></div><div class="field"><label>Display name</label><input autocomplete="off" id="user-name" placeholder="Teammate"></div><div class="field"><label>Role</label><select id="user-role">${option(['admin','member'],'member')}</select></div><div class="field"><label>Work groups</label><div class="work-group-options">${(state.statuses.work_groups||['Engineering','QA','Management']).map(g=>`<label class="work-group-option"><input autocomplete="off" type="checkbox" name="user-group" value="${g}"><span>${g==='Management'?'Manager':g}</span></label>`).join('')}</div></div><div class="field"><label class="work-group-option"><input autocomplete="off" type="checkbox" id="user-language-switch"><span>Allow language switching</span></label><p class="muted-note">${ui("Off by default. Enable to let this member switch between 中文 and English. Without it, the interface stays in English.")}</p></div><div class="report-intro">${ui("Engineering and QA are independent of system role. Management provides the team overview. Combine it with a work group to enable My work and Team overview. Admin permissions come from the system role. Set a password after saving.")}</div>`;
 }
 $('#modal-content').classList.toggle('task-create-modal',kind==='task');
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-close="modal">×</button></div>${markup}<div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" data-save-modal="${kind}">${kind==='task'?'Create task':'Save record'}</button></div>`;
 $('#modal-shade').classList.remove('hidden');
 if(kind==='task'){syncNewWorkKind();markSuggestedDefaults($('#modal-content'),'[data-key^="new-"],#new-category');}
 if(kind==='user')markSuggestedDefaults($('#modal-content'),'#user-role');
 if(kind==='office'){const selected=state.privateItems.find(i=>i.id===workItem);$('#office-title').value=selected?.title||'';$('#office-title').dataset.autoTitle=selected?.title||'';setDailyEntryMode(mode);syncOfficeRecurrence();syncDailyTaskCompletionDate();markSuggestedDefaults($('#modal-content'),'#office-title,#office-date,#office-category,#office-status,#daily-task-status,#daily-task-recurrence,#daily-task-due');}
}
function syncDailyTaskCompletionDate(){const field=$('#daily-task-completed-date-field'),status=$('#daily-task-status');if(field)field.hidden=status.value!=='Completed';const choice=status?.querySelector('option[value="Completed"]');if(choice)choice.textContent=$('#daily-task-recurrence')?.value!=='none'?'Complete this occurrence':'Completed';}
function setDailyEntryMode(mode){if(editingOfficeId||savedDailyTaskId)return;const task=mode==='task';$('#daily-entry-mode').value=task?'task':'activity';$('#daily-activity-fields').hidden=task;$('#daily-task-fields').hidden=!task;for(const b of document.querySelectorAll('[data-daily-mode]'))b.setAttribute('aria-pressed',String(b.dataset.dailyMode===(task?'task':'activity')));const save=document.querySelector('[data-save-modal="office"]');if(save)save.textContent=task?'Add task':'Save activity';}
function closeModal(){if(newTaskSaving)return;const createdTask=savedNewTaskId;savedNewTaskId=null;pendingNewTaskFiles=[];if(createdTask)busy(async()=>{await reload();await openDetail(createdTask);});if(pendingTaskField){pendingTaskField.cancel();pendingTaskField=null;}$('#modal-shade').classList.add('hidden');$('#modal-content').classList.remove('image-preview','task-create-modal')}
async function saveModal(kind){
 if(kind==='task'){
 const button=document.querySelector('[data-save-modal="task"]');if(newTaskSaving||button.disabled)return;newTaskSaving=true;button.disabled=true;
 try{
  if(!savedNewTaskId){
   const p={work_kind:$('#new-work-kind')?.value||'Engineering',planning_status:$('#new-planning-status')?.value||'Active',work_category:$('#new-work-category')?.value||'',title:$('#new-title').value,type:document.querySelector('[data-key="new-type"]').value,priority:document.querySelector('[data-key="new-priority"]').value,category:$('#new-category').value,parent_task_id:$('#new-parent').value,description:$('#new-description').value,assignee:$('#new-assignee').value,next_action_owner:$('#new-assignee').value,activity_date:todayDate()};
   const d=await api('/tasks',{method:'POST',body:JSON.stringify(p)});savedNewTaskId=d.id;
   for(const field of document.querySelectorAll('#modal-content .task-create-section:not(.task-create-attachments) input,#modal-content .task-create-section:not(.task-create-attachments) select,#modal-content .task-create-section:not(.task-create-attachments) textarea,#modal-content .task-create-section:not(.task-create-attachments) button'))field.disabled=true;
  }
  const failed=await saveNewTaskFiles(savedNewTaskId);
  if(failed){const msg='Task created. Some files could not upload. Retry uploads to attach the remaining files without creating another task.';systemText($('#new-task-upload-error'),msg);systemText(button,'Retry uploads');systemText(document.querySelector('#modal-content .form-actions [data-close="modal"]'),'View task');showToast(msg,true);return;}
  const tid=savedNewTaskId;savedNewTaskId=null;newTaskSaving=false;closeModal();await reload();showToast('New task created');await openDetail(tid);
 }finally{newTaskSaving=false;button.disabled=false;}
 }else if(kind==='office'){
 const button=document.querySelector('[data-save-modal="office"]');if(button.disabled)return;button.disabled=true;
 try{
  const taskMode=!editingOfficeId&&$('#daily-entry-mode').value==='task',mode=taskMode?'task':'activity';let target;
  if(taskMode){const body={kind:'Task',status:$('#daily-task-status').value,title:$('#daily-task-title').value,description:$('#daily-task-description').value,parent_id:$('#daily-task-parent').value,...readRecurrence('daily-task'),...($('#daily-task-status').value==='Completed'?{completed_date:$('#daily-task-completed-date').value}:{})};const result=await api('/private-work'+(savedDailyTaskId?'/'+savedDailyTaskId:''),{method:savedDailyTaskId?'PATCH':'POST',body:JSON.stringify(body)});savedDailyTaskId=savedDailyTaskId||result.id;if(result.occurrence_completed){$('#daily-task-status').value='In Progress';$('#daily-task-due').value=result.next_due_date;syncDailyTaskCompletionDate();}target={private_work_id:savedDailyTaskId};}
  else{const body={title:$('#office-title').value,work_date:$('#office-date').value,category:$('#office-category').value,status:$('#office-status').value,...($('#office-minutes-field')?.hidden?{}:{minutes:Number($('#office-minutes')?.value||0)}),details:$('#office-details').value,work_item_id:$('#office-item').value};body.complete_task=!!$('#office-complete-task')?.checked;if(!$('#office-recurrence-controls').hidden)body.complete_occurrence=$('#office-complete-cycle').checked;if(body.complete_task||body.complete_occurrence)body.status='Completed';const result=await api('/office'+(editingOfficeId?'/'+editingOfficeId:''),{method:editingOfficeId?'PATCH':'POST',body:JSON.stringify(body)});editingOfficeId=editingOfficeId||result.id;target={office_id:editingOfficeId};}
  $('.daily-entry-mode').hidden=true;if(taskMode)$('#daily-task-parent').disabled=true;
  const failed=await saveDailyImages(pendingDailyFiles[mode],target);
  if(failed){const msg='Work saved. Some images could not upload; click Save again to retry without creating another record.';systemText($('#daily-upload-error'),msg);await loadDaily();if(state.privateDetail)await refreshPrivateDetail();showToast(msg,true);return;}
  closeModal();await reload();if(taskMode)await openPrivateDetail(target.private_work_id);showToast(taskMode?'Private task added':'Private daily work saved');
 }finally{button.disabled=false;}
 }else if(kind==='user'){
 await api('/users',{method:'POST',body:JSON.stringify({email:$('#user-email').value,display_name:$('#user-name').value,role:$('#user-role').value,language_switch_enabled:$('#user-language-switch').checked,groups:[...document.querySelectorAll('[name="user-group"]:checked')].map(x=>x.value),is_boss:!!document.querySelector('[name="user-group"][value="Management"]:checked')})});closeModal();await reload();showToast('Team member saved');
 }
}
async function saveTask(){const t=state.detailData.task,patch={activity_date:$('#status-work-date').value};for(const f of document.querySelectorAll('.task-field')){const k=f.dataset.key;if(Object.hasOwn(t,k)&&!f.disabled&&f.value!==String(t[k]??''))patch[k]=f.value;}if(Object.keys(patch).length===1){showToast('No changes to save');return}await api('/tasks/'+t.id,{method:'PATCH',body:JSON.stringify(patch)});await reload();showToast('Task changes recorded in timeline')}
async function addActivity(){const tid=state.detail,button=$('#add-activity');button.disabled=true;try{const kind=document.querySelector('[data-key="activity-action"]').value;const d=await api('/tasks/'+tid+'/activity',{method:'POST',body:JSON.stringify({action_type:kind,advance_workflow:false,activity_date:$('#activity-date').value,environment:$('#activity-env').value,environment_override:$('#activity-env').dataset.manual==='1',result:$('#activity-result').value,notes:$('#activity-notes').value,minutes:Number($('#activity-minutes')?.value||0),work_role:$('#activity-role')?.value||''})});const files=pendingActivityFiles;pendingActivityFiles=[];$('#activity-notes').value='';$('#activity-result').value='';try{await uploadTaskFiles(files,{activityId:d.id});}catch(error){await refreshTaskDetail();throw new Error('Activity saved; some files could not upload. Open Edit activity to add them.');}await reload();document.querySelectorAll('.task-secondary').forEach(d=>{if(d.querySelector('summary')?.textContent==='Activity timeline')d.open=true});showToast('Work activity saved');}finally{button.disabled=false;}}
async function addComment(){const tid=state.detail,button=$('#add-comment');button.disabled=true;try{const d=await api('/tasks/'+tid+'/comments',{method:'POST',body:JSON.stringify({body:$('#comment-body').value,reply_to:state.replyTo,action_owners:[...($('#comment-action-owners')?.selectedOptions||[])].map(x=>x.value)})});state.replyTo=null;const files=pendingCommentFiles;pendingCommentFiles=[];$('#comment-body').value='';try{await uploadTaskFiles(files,{commentId:d.id});}catch(error){await refreshTaskDetail();throw new Error('Comment saved; some images could not be uploaded. Add them to that comment to retry.');}await reload();document.querySelectorAll('.task-secondary').forEach(d=>{if(d.querySelector('summary')?.textContent==='Discussion')d.open=true});$('#detail-panel').scrollTop=0;showToast('Comment posted');}finally{button.disabled=false;}}
async function uploadFile(pastedFile){const file=pastedFile instanceof File?pastedFile:$('#file-input').files[0];if(!file)throw new Error('Select a file');const form=new FormData();form.append('file',file);form.append('task_id',state.detail);await api('/attachments',{method:'POST',body:form});await reload();showToast('Attachment uploaded')}
async function syncPR(){const d=await api('/tasks/'+state.detail+'/sync-pr',{method:'POST'});await reload();showToast('GitHub: '+d.status)}
async function downloadFile(id,filename){
 const h={};if(state.local)h['x-dev-user']=$('#demo-user').value;
 const resp=await fetch('/api/attachments/'+encodeURIComponent(id),{headers:h});if(!resp.ok)throw new Error('Unable to download attachment');
 const blob=await resp.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=filename||'attachment';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
}
async function downloadExport(){
 const h={};if(state.local)h['x-dev-user']=$('#demo-user').value;
 const resp=await fetch('/api/export',{headers:h});if(!resp.ok)throw new Error('Export permission denied');
 const blob=await resp.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='work-tracker-backup-'+state.day+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
}
let filterTimer;
document.addEventListener('click',ev=>{
 const scope=ev.target.closest('[data-board-scope]');if(scope){state.boardScope=scope.dataset.boardScope;state.boardPhase='all';render();return;}
 const phase=ev.target.closest('[data-board-phase]');if(phase){state.boardPhase=phase.dataset.boardPhase;render();document.querySelector('[data-board-phase="'+state.boardPhase+'"]')?.focus();return;}
 const toggle=ev.target.closest('[data-board-filters-toggle]');if(toggle){state.boardFiltersOpen=!state.boardFiltersOpen;render();document.querySelector('[data-board-filters-toggle]')?.focus();return;}
 const clear=ev.target.closest('[data-clear-board-filter]');if(clear){clearTimeout(filterTimer);clearBoardFilters(clear.dataset.clearBoardFilter);render();document.querySelector('[data-board-filters-toggle]')?.focus();}
});

document.addEventListener('click',ev=>{
 const download=ev.target.closest('[data-download]');if(download)return busy(()=>downloadFile(download.dataset.download,download.dataset.filename));
 const activityRow=ev.target.closest('[data-row-activity]');if(activityRow)return busy(()=>openDashboardActivity(activityRow.dataset.activityTask,activityRow.dataset.rowActivity));
 const open=ev.target.closest('[data-open]');if(open)return busy(()=>openDetail(open.dataset.open));
 const privateRow=ev.target.closest('[data-row-private]');if(privateRow&&!ev.target.closest('button,input,select,a'))return busy(()=>openPrivateDetail(privateRow.dataset.rowPrivate));
 const officeRow=ev.target.closest('[data-row-office]');if(officeRow&&!ev.target.closest('button,input,select,a'))return busy(()=>editOffice(officeRow.dataset.rowOffice));
 const row=ev.target.closest('[data-row-task]');if(row&&!ev.target.closest('button,input,select,a'))return busy(()=>openDetail(row.dataset.rowTask));
 const view=ev.target.closest('[data-view]');if(view)return setView(view.dataset.view);
 const mk=ev.target.closest('[data-modal]');if(mk)return modal(mk.dataset.modal);
 const close=ev.target.closest('[data-close]');if(close)return close.dataset.close==='detail'?closeDetail():closeModal();
 const tab=ev.target.closest('[data-tab]');if(tab)return changeTab(tab.dataset.tab);
 const sv=ev.target.closest('[data-save-modal]');if(sv)return busy(()=>saveModal(sv.dataset.saveModal));
 if(ev.target.id==='save-task')return busy(saveTask);
 if(ev.target.id==='add-activity')return busy(addActivity);
 if(ev.target.id==='add-comment')return busy(addComment);
 if(ev.target.id==='upload-file')return busy(uploadFile);
 if(ev.target.id==='sync-pr')return busy(syncPR);
 if(ev.target.id==='download-export')return busy(downloadExport);
});
document.addEventListener('change',ev=>{
 if(ev.target.matches('[data-day]'))return busy(async()=>{state.day=ev.target.value;state.summary=await api('/summary?date='+state.day);render();});
 if(ev.target.id==='board-people'){state.boardPeople=ev.target.value;render();$('#board-people')?.focus();return;}
 if(ev.target.id==='private-work-status'){state.privateStatus=ev.target.value;renderPrivateWork();return;}
 if(ev.target.id==='daily-email'){state.dailyEmail=ev.target.value;return busy(loadDaily)}
 const boardFields={'dev-filter':'devFilter','qa-filter':'qaFilter','category-filter':'categoryFilter'};
 if(boardFields[ev.target.id]){state[boardFields[ev.target.id]]=ev.target.value;render();$('#'+ev.target.id)?.focus();return;}
 if(ev.target.id==='board-sort'){state.boardSort=ev.target.value==='Manual order'?'manual':ev.target.value==='Recently updated'?'recent':'priority';render();$('#board-sort')?.focus();}

});
document.addEventListener('input',ev=>{if(ev.target.id==='private-work-search'){state.privateSearch=ev.target.value;renderPrivateBoardRows();return;}if(ev.target.id==='task-search'||ev.target.id==='history-search'){state.filter=ev.target.value;clearTimeout(filterTimer);const id=ev.target.id;filterTimer=setTimeout(()=>{const pos=ev.target.selectionStart;render();const input=$('#'+id);if(input){input.focus();input.setSelectionRange(pos,pos)}},150)}});
$('#panel-shade').addEventListener('click',closeDetail);
$('#modal-shade').addEventListener('click',ev=>{if(ev.target.id==='modal-shade')closeModal()});

$('#demo-user').addEventListener('change',()=>busy(async()=>{const d=await api('/me');state.user=d.user;state.workspaceMode='personal';state.boardPeople='all';state.workspaceRevision++;state.instructions=d.instructions;state.filter='';state.dailyEmail='';state.view='dashboard';closeDetail();await reload();$('#account-profile').hidden=false;$('#login-entry').hidden=true;$('#nav').hidden=false;$('.top-actions').hidden=false;$('#current-user').textContent=state.user.display_name||who(state.user.email);$('#current-role').textContent=(state.user.groups||[]).map(g=>g==='Management'?'Manager':g).join(', ');updateProfileAvatars();$('#team-nav').hidden=!canManage();$('#admin-nav').hidden=!canManage();$('#history-nav').hidden=!canManage();document.querySelectorAll('#nav [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view==='dashboard'));$('#crumb').textContent='Dashboard';showToast('Previewing '+who(state.user.email))}));
function escapeError(v){return e(v)}
async function showLogin(){
 state.user=null;updateProfileAvatars();globalThis.WorkTrackerLanguage?.configure(null);state.workspaceMode='personal';state.boardPeople='all';state.workspaceRevision++;$('#workspace-switch').hidden=true;state.instructions={guides:[],acknowledged:[]};state.tasks=[];state.office=[];state.activities=[];state.users=[];state.summary=null;state.privateItems=[];state.privateAttachments=[];releaseList=[];state.archivedTasks=[];closeDetail(true);
 $('#account-profile').hidden=true;$('#login-entry').hidden=false;$('#nav').hidden=true;$('.top-actions').hidden=true;
 const status=await api('/auth/status');
 $('#content').innerHTML=`<div class="auth-card"><div class="eyebrow">WORK TRACKER</div><h1>${status.setupAvailable?'Set your password':'Sign in'}</h1><p class="subtitle">${ui("Use your Work Tracker email and password.")}</p><form autocomplete="on" id="login-form"><div class="field"><label for="login-email">Email</label><input autocomplete="username" id="login-email" type="email" value="${e(status.setupEmail||'')}" ${status.setupAvailable?'readonly':''} required></div><div class="field"><label for="login-password">Password</label><input autocomplete="${status.setupAvailable?'new-password':'current-password'}" id="login-password" type="password" ${status.setupAvailable?'minlength="12"':''} maxlength="256" required></div><p id="login-error" role="alert"></p><button class="btn primary" type="submit">${status.setupAvailable?'Set password and sign in':'Sign in'}</button></form>${status.setupAvailable?`<p class="muted-note">${ui("Choose at least 12 characters.")}</p>`:''}</div>`;
 $('#login-form').onsubmit=async ev=>{ev.preventDefault();const btn=ev.target.querySelector('button');btn.disabled=true;$('#login-error').textContent='';try{await api(status.setupAvailable?'/auth/setup':'/auth/login',{method:'POST',body:JSON.stringify({email:$('#login-email').value,password:$('#login-password').value})});await load();}catch(error){$('#login-error').textContent=error.message;}finally{btn.disabled=false}};
}
$('#login-entry').onclick=()=>busy(showLogin);
$('#logout').onclick=()=>busy(async()=>{await api('/auth/logout',{method:'POST'});await showLogin()});
(async()=>{try{await load();}catch{await showLogin();}})();
const renderOrig=render;render=function(){renderOrig();if(state.view==='daily')busy(loadDaily)};

document.addEventListener('paste',ev=>{if(ev.target.closest('#account-avatar-settings')){const photos=[...(ev.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/'));if(photos.length){ev.preventDefault();busy(()=>saveAccountAvatar(photos[0]));}return;}if(!canWrite())return;const creating=ev.target.closest('#modal-content.task-create-modal');const daily=ev.target.closest('#daily-activity-fields,#daily-task-fields');const files=[...(ev.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/'));if(files.length){if(creating){ev.preventDefault();queueEvidence(files,'new-task');}else if(ev.target.closest('#private-activity-form')){ev.preventDefault();queueEvidence(files,'private-activity');}else if(daily){ev.preventDefault();queueEvidence(files,daily.id==='daily-task-fields'?'daily-task':'daily-activity');}else if(state.privateDetail&&ev.target.closest('#private-task-evidence,#private-project-edit-evidence')){ev.preventDefault();busy(()=>uploadPrivateTaskImages(files));}else if(state.detail&&!state.detailData?.task.archived){ev.preventDefault();evidencePaste(files,ev.target)}}});

function passwordModal(email=state.user.email){
 const self=email===state.user.email,title=self?'Change password':state.users.find(u=>u.email===email)?.has_password?'Reset password':'Set password';
 $('#modal-content').classList.remove('image-preview','task-create-modal');
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-close="modal">×</button></div><p class="muted-note">${e(email)}</p>${instructionFor("account")}<form autocomplete="off" id="member-password-form">${self?'<div class="field"><label for="current-password">Current password</label><input autocomplete="off" id="current-password" type="password" maxlength="256" required></div>':''}<div class="field"><label for="member-password">New password</label><input autocomplete="off" id="member-password" type="password" minlength="12" maxlength="256" required><p class="muted-note">${ui("Use at least 12 characters.")}</p></div><div class="field"><label for="confirm-password">Confirm new password</label><input autocomplete="off" id="confirm-password" type="password" minlength="12" maxlength="256" required></div><p id="password-error" class="danger-link" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close="modal">Cancel</button><button class="btn primary" type="submit">${self?'Change password':'Save password'}</button></div></form>`;
 $('#modal-shade').classList.remove('hidden');
 $('#member-password-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('[type="submit"]');if(button.disabled)return;$('#password-error').textContent='';if($('#member-password').value!==$('#confirm-password').value){systemText($('#password-error'),'New passwords do not match.');return;}button.disabled=true;try{await api('/password',{method:'POST',body:JSON.stringify({email,password:$('#member-password').value,current_password:$('#current-password')?.value})});closeModal();if(self){await showLogin();$('#login-email').value=email;showToast('Password updated. Sign in with your new password.')}else{await reload();showToast('Password saved. Share it privately with this member.')}}catch(error){$('#password-error').textContent=error.message;}finally{button.disabled=false;}};
}
$('#change-password').onclick=()=>passwordModal();
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-password-email]');if(button)passwordModal(button.dataset.passwordEmail);});

function syncUserRoleGroups(){const groups=[...document.querySelectorAll('[name="user-group"]:checked')].map(input=>input.value),managerOnly=groups.includes('Management')&&!groups.some(g=>g!=='Management'),roleInput=$('#user-role');if(roleInput){if(managerOnly)roleInput.value='member';roleInput.disabled=managerOnly;}}
document.addEventListener('change',ev=>{if(ev.target.matches('[name="user-group"]'))syncUserRoleGroups();});
let releaseList=[],selectedRelease='',releaseEditorOpen=false;
const releaseOrder=(a,b)=>a.planned_date.localeCompare(b.planned_date)||String(a.created_at||'').localeCompare(String(b.created_at||''))||a.id.localeCompare(b.id);
const releaseReady=t=>['On Production','Closed'].includes(t?.development_status);
async function loadReleases(){const revision=state.workspaceRevision;const [d,t]=await Promise.all([api('/releases'),api('/tasks')]);if(state.view!=='releases'||state.workspaceRevision!==revision)return;releaseList=d.releases;state.tasks=t.tasks;if(!releaseList.some(r=>r.id===selectedRelease))selectedRelease=releaseList.filter(r=>r.status==='Planned').sort(releaseOrder)[0]?.id||releaseList[0]?.id||'';renderReleases()}
function openReleasePlan(){
 if(!canDev()||state.view!=='releases')return;
 $('#modal-content').classList.remove('image-preview','task-create-modal');
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>Plan a version</h2><button class="close" data-close="modal" aria-label="Close plan">×</button></div><p class="muted-note">${ui('Schedule a future version, including next month. You can choose its tasks after creating the plan.')}</p><form autocomplete="off" id="release-plan-form"><div class="field"><label for="plan-version-name">Version name *</label><input autocomplete="off" id="plan-version-name" required maxlength="60" placeholder="${e(tr('e.g. v1.2.0'))}" data-ui-placeholder="e.g. v1.2.0"></div><div class="field"><label for="plan-version-date">Planned date *</label><input autocomplete="off" id="plan-version-date" required type="date"></div><div class="field"><label for="plan-version-notes">Plan notes</label><textarea autocomplete="off" id="plan-version-notes" placeholder="${e(tr('e.g. Improve search and fix the sign-in issue.'))}" data-ui-placeholder="e.g. Improve search and fix the sign-in issue."></textarea></div><p id="plan-version-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close="modal">Cancel</button><button type="submit" class="btn primary">Create plan</button></div></form>`;
 $('#modal-shade').classList.remove('hidden');$('#plan-version-name').focus();
 $('#release-plan-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;$('#plan-version-error').textContent='';try{const created=await api('/releases',{method:'POST',body:JSON.stringify({version:$('#plan-version-name').value,planned_date:$('#plan-version-date').value,notes:$('#plan-version-notes').value})});selectedRelease=created.id;releaseEditorOpen=true;closeModal();await loadReleases();$('#release-detail')?.scrollIntoView({block:'nearest',behavior:'smooth'});showToast('Version plan created');}catch(error){$('#plan-version-error').textContent=error.message;}finally{button.disabled=false;}};
}
document.addEventListener('click',ev=>{if(ev.target.closest('#plan-version'))openReleasePlan();});
function releaseItems(r){const ids=JSON.parse(r.task_ids_json||'[]');return r.status==='Released'?JSON.parse(r.snapshot_json||'[]'):state.tasks.filter(t=>ids.includes(t.id));}
function releasePreview(r){const items=releaseItems(r),projects=[...new Set(items.map(t=>t.project).filter(p=>p&&p!=='CRM'))];return `<div class="version-preview">${projects.length?`<p class="version-projects">${e(projects.join(' · '))}</p>`:''}${items.length?`<ul class="version-changes">${items.slice(0,5).map(t=>`<li><button type="button" class="version-task-link" data-open="${e(t.id)}">${e(t.title)}</button>${r.status==='Planned'?`<span class="release-readiness ${releaseReady(t)?'ready':'pending'}">${releaseReady(t)?'Ready for release':'Not ready'}</span>`:''}</li>`).join('')}</ul>${items.length>5?`<p class="muted-note">${ui('{count} more changes',{count:items.length-5})}</p>`:''}`:`<p class="muted-note">${ui('No tasks selected. Open the plan to choose Engineering Board tasks.')}</p>`}${r.notes?`<p class="version-notes-preview">${e(r.notes.slice(0,220))}${r.notes.length>220?'…':''}</p>`:''}</div>`;}
function renderReleases(){
 const root=$('#release-results');if(!root)return;
 const ordered=releaseList.slice().sort((a,b)=>Number(b.status==='Planned')-Number(a.status==='Planned')||(a.status==='Planned'?releaseOrder(a,b):String(b.released_date||b.planned_date).localeCompare(String(a.released_date||a.planned_date)))),next=ordered.find(r=>r.status==='Planned');
 root.innerHTML=`<div class="release-toolbar"><span class="muted-note">${ui('Keep future plans here. The next Wednesday plan opens after the current version is released.')}</span></div><div class="version-card-list">${ordered.map(r=>{const open=releaseEditorOpen&&r.id===selectedRelease;return `<section class="version-card ${r.status==='Planned'?'is-planned':''}"><button type="button" class="version-card-head" data-release="${e(r.id)}" aria-expanded="${open}"><span><strong>${r.status==='Planned'?(r.id===next.id?'Next release':'Planned release'):'Previous release'} · ${e(dateFmt(r.released_date||r.planned_date))}</strong><small>${e(r.version)}</small></span>${badge(r.status)}</button>${releasePreview(r)}<div class="version-card-footer"><button type="button" class="account-link" data-release="${e(r.id)}" aria-expanded="${open}">${open?'Close details':r.status==='Planned'&&canDev()?'Review plan':'View details'}</button></div>${open?`<div class="version-expanded" id="release-detail">${releaseDetail(r)}</div>`:''}</section>`;}).join('')||empty('No versions yet','Use + Plan to schedule a version.')}</div>`;
 root.querySelectorAll('[data-release]').forEach(b=>b.onclick=()=>{releaseEditorOpen=selectedRelease!==b.dataset.release||!releaseEditorOpen;selectedRelease=b.dataset.release;renderReleases()});
 $('#release-save')?.addEventListener('click',()=>busy(()=>saveRelease(false)));
 $('#release-publish')?.addEventListener('click',()=>busy(()=>saveRelease(true)));
 root.querySelectorAll('[name="release-task"],#release-actual').forEach(input=>input.addEventListener('change',updateReleaseReadiness));updateReleaseReadiness();
}
function updateReleaseReadiness(){const button=$('#release-publish');if(!button)return;const items=[...document.querySelectorAll('[name="release-task"]:checked')].map(input=>state.tasks.find(t=>t.id===input.value)),ready=items.filter(releaseReady),pending=items.length-ready.length;button.disabled=!ready.length||!$('#release-actual')?.value;const message=!ready.length?'Select at least one task that is On Production or Closed.':!$('#release-actual')?.value?'Choose the actual release date.':pending?'Ready tasks enter this release. Selected unfinished tasks move to the next plan.':'Ready to record this release.';systemText($('#release-ready-note'),message);}
function releaseReservation(tid,rid){return releaseList.find(r=>r.id!==rid&&r.status==='Planned'&&(r.selected_task_ids||JSON.parse(r.task_ids_json||'[]')).includes(tid));}
function releaseTaskPicker(r){
 const ids=JSON.parse(r.task_ids_json||'[]'),delivered=new Set(releaseList.filter(x=>x.status==='Released').flatMap(x=>JSON.parse(x.task_ids_json||'[]'))),available=state.tasks.filter(t=>(!t.work_kind||t.work_kind==='Engineering')&&!delivered.has(t.id));
 const groups=[{title:'Ready for release',description:'On Production or Closed. Selected tasks enter the released changes.',items:available.filter(t=>releaseReady(t)&&!releaseReservation(t.id,r.id))},{title:'Not ready',description:'Still in development or QA. Selected tasks move to the next plan when this version is released.',items:available.filter(t=>!releaseReady(t)&&!releaseReservation(t.id,r.id))},{title:'In another plan',description:'Remove a task from its current plan before selecting it here.',items:available.filter(t=>releaseReservation(t.id,r.id))}];
 return `<div class="release-task-picker">${groups.map(g=>g.items.length?`<section class="release-picker-group"><div class="release-picker-heading"><h4>${g.title}</h4><p>${ui(g.description)}</p></div>${g.items.map(t=>{const reserved=releaseReservation(t.id,r.id);return `<label class="release-task-option ${reserved?'is-reserved':''}"><input autocomplete="off" type="checkbox" name="release-task" value="${e(t.id)}" ${ids.includes(t.id)?'checked':''} ${reserved?'disabled':''}><span><strong>${e(t.title)}</strong><small>${r.auto_candidates?.includes(t.id)?'Auto · ':''}${e(t.type)} · ${e(t.development_status)} · QA: ${e(t.qa_status)}</small>${reserved?`<small>${ui('Selected in {version}',{version:reserved.version})}</small>`:''}</span></label>`;}).join('')}</section>`:'').join('')||`<p class="muted-note">${ui(state.tasks.length?'All available tasks are already in released versions.':'No Engineering Board tasks yet.')}</p>`}</div>`;
}
function releaseDetail(r){const released=r.status==='Released',editable=canDev()&&!released,ids=JSON.parse(r.task_ids_json),items=releaseItems(r);const categories=['New Feature','Bug Fix','Improvement','UI/UX','Investigation'];
 const carried=JSON.parse(r.deferred_task_ids_json||'[]').length,next=releaseList.find(x=>x.id===r.rollover_release_id);
 return `<div class="version-detail-heading"><h3 class="card-title">${released?'Release details':editable?'Edit release plan':'Plan details'}</h3><span class="muted-note">${ui(released?'Historical snapshot':'Estimates may change')}</span></div><div class="release-breakdown">${categories.map(c=>{const ts=items.filter(t=>t.type===c);return ts.length?`<h4>${e(c)}</h4><ul>${ts.map(t=>`<li><button type="button" class="version-task-link" data-open="${e(t.id)}">${e(t.title)}</button>${badge(t.development_status)}</li>`).join('')}</ul>`:''}).join('')}</div>${released&&carried?`<p class="release-carry-note">${ui('{count} unfinished tasks moved to {version}.',{count:carried,version:next?.version||'the next plan'})}</p>`:''}${r.auto_candidates?`<p class="muted-note">${ui('Automatically includes tasks moved to On Production from {start} through {end}. Tasks reserved for future plans stay in those plans. Uncheck and save to exclude.',{start:dateFmt(r.auto_start),end:dateFmt(r.auto_end)})}</p>`:''}<div class="field"><label for="release-notes">Release notes</label><textarea autocomplete="off" id="release-notes" ${editable?'':'disabled'}>${e(r.notes)}</textarea></div>${editable?`<div class="field"><label for="release-version">Version name *</label><input autocomplete="off" id="release-version" maxlength="60" value="${e(r.version)}" placeholder="${e(tr('e.g. v1.2.0'))}" data-ui-placeholder="e.g. v1.2.0"></div><div class="version-plan-fields"><div class="field"><label for="release-planned">Planned date</label><input autocomplete="off" id="release-planned" type="date" value="${e(r.planned_date)}"></div><div class="field"><label for="release-actual">Actual release date</label><input autocomplete="off" id="release-actual" type="date" data-suggested="true" class="suggested-value" value="${todayDate()}" aria-describedby="release-date-help"><p class="muted-note" id="release-date-help">${ui('Defaults to today. Check the date before confirming the release.')}</p></div></div><h3 class="release-category">Include Engineering Board tasks</h3>${releaseTaskPicker(r)}<p class="muted-note">${ui('Select both delivered and planned work. Confirming a release includes only On Production or Closed tasks and carries unfinished tasks to the next plan.')}</p><div class="version-confirm-row"><span class="muted-note" id="release-ready-note" role="status"></span><div class="form-actions"><button type="button" class="btn" id="release-save">Save plan</button><button type="button" class="btn primary" id="release-publish" disabled>Confirm actual release</button></div></div>`:''}`;
}
async function submitRelease(body,rid){const result=await api('/releases/'+rid,{method:'PATCH',body:JSON.stringify(body)});await loadReleases();showToast(body.publish?(result.deferred_task_ids?.length?'Release recorded. Unfinished tasks moved to the next plan.':'Release recorded and locked'):'Release plan saved');return result;}
async function saveRelease(publish){
 if(!canDev())return;
 if(publish&&!$('#release-actual').value){$('#release-actual').focus();showToast('Choose the actual release date',true);return;}if(!$('#release-version').value.trim()){$('#release-version').focus();showToast('Version name is required',true);return;}if(!$('#release-planned').value){$('#release-planned').focus();showToast('Choose the planned release date',true);return;}
 const r=releaseList.find(x=>x.id===selectedRelease),rid=r.id,body={version:$('#release-version').value,task_ids:[...document.querySelectorAll('[name="release-task"]:checked')].map(x=>x.value),notes:$('#release-notes').value,planned_date:$('#release-planned').value,plan_revision:r.plan_revision,publish,released_date:$('#release-actual').value};
 if(!publish){const button=$('#release-save');if(button.disabled)return;button.disabled=true;try{await submitRelease(body,rid);}finally{button.disabled=false;}return;}
 const tasks=state.tasks.filter(t=>body.task_ids.includes(t.id)),ready=tasks.filter(releaseReady),pending=tasks.filter(t=>!releaseReady(t));if(!ready.length){showToast('Select at least one task that is On Production or Closed',true);return;}
 $('#modal-content').classList.remove('image-preview','task-create-modal');
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>Confirm actual release?</h2><button class="close" data-close="modal">×</button></div><p class="muted-note">${e(body.version)} · ${e(dateFmt(body.released_date))}</p><div class="release-confirm-group"><h3>In this release</h3><ul>${ready.map(t=>`<li>${e(t.title)}</li>`).join('')}</ul></div>${pending.length?`<div class="release-confirm-group"><h3>Move to next plan</h3><ul>${pending.map(t=>`<li>${e(t.title)} <span class="muted-note">· ${e(t.development_status)}</span></li>`).join('')}</ul><p class="muted-note">${ui('These tasks remain unfinished and move to the next version plan. A next Wednesday plan is created if needed.')}</p></div>`:''}<p class="muted-note">${ui('Recording a release updates this tracker; it does not deploy the engineering code. Released records are locked.')}</p><p id="release-confirm-error" role="alert"></p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-release">Confirm release</button></div>`;
 $('#modal-shade').classList.remove('hidden');$('#confirm-release').onclick=async()=>{const button=$('#confirm-release');if(button.disabled)return;button.disabled=true;try{await submitRelease(body,rid);closeModal();}catch(error){$('#release-confirm-error').textContent=error.message;}finally{button.disabled=false;}};
}

document.addEventListener('click',ev=>{const button=ev.target.closest('[data-edit-user]');if(!button||!canManage())return;const u=state.users.find(x=>x.email===button.dataset.editUser);if(!u)return;modal('user');$('#modal-content h2').textContent='Edit team member';$('#user-email').value=u.email;$('#user-email').readOnly=true;$('#user-name').value=u.display_name;$('#user-role').value=u.role;$('#user-language-switch').checked=Number(u.language_switch_enabled)===1;clearSuggestedValue($('#user-role'));const groups=JSON.parse(u.groups_json||'[]');document.querySelectorAll('[name="user-group"]').forEach(x=>x.checked=groups.includes(x.value));syncUserRoleGroups();const note=$('#modal-content .report-intro');note.textContent='Update name, role and work groups. Saving these changes preserves the existing password.';const wrap=document.createElement('div');wrap.className='form-actions';{const b=document.createElement('button');b.className='btn';b.dataset.passwordEmail=u.email;b.textContent=u.has_password?'Reset password':'Set password';wrap.append(b);note.after(wrap);}});

async function loadManagerOverview(){
 const revision=state.workspaceRevision,day=state.day;const [daily,engineering,versions]=await Promise.all([api('/daily?scope=team&date='+day),api('/engineering-daily?date='+day),api('/releases')]);
 if(revision!==state.workspaceRevision||state.view!=='dashboard'||!isBoss()||day!==state.day)return;
 const root=$('#manager-results');if(!root)return;
 const events=[...daily.activities.map(a=>({person:a.actor_email,title:a.task_title,id:a.task_id,status:a.result,notes:a.notes,time:a.created_at})),...daily.office.map(a=>({person:a.owner_email,title:a.title,status:a.status,notes:a.details,time:a.created_at}))].sort((a,b)=>b.time.localeCompare(a.time));
 const personRows=events.map(a=>`<tr><td>${e(who(a.person))}</td><td>${a.id?`<div class="title-cell" data-open="${e(a.id)}">${e(a.title)}</div>`:e(a.title)}</td><td>${a.id?e(a.status||'—'):'—'}</td><td class="work-notes">${e(a.notes||'—')}</td></tr>`).join('');
 const upcoming=versions.releases.filter(r=>r.status==='Planned').sort((a,b)=>a.planned_date.localeCompare(b.planned_date));
 const releaseRows=upcoming.slice(0,2).map((r,i)=>{const ids=JSON.parse(r.task_ids_json),tasks=state.tasks.filter(t=>ids.includes(t.id));return `<div class="list-row"><div class="list-main"><div class="eyebrow">${i===0?'NEXT RELEASE':'FOLLOWING RELEASE'}</div><div class="list-title">${e(r.version)} · ${e(dateFmt(r.planned_date))}</div><div class="list-meta">${tasks.filter(t=>t.type==='New Feature').length} new features · ${tasks.filter(t=>t.type==='Bug Fix').length} bug fixes · ${tasks.length} planned changes</div><div class="muted-note">${tasks.map(t=>e(t.title)).join(' · ')||'No tasks selected yet'}</div></div></div>`}).join('');
 const changes=engineering.activities.map(a=>`<tr><td>${e(who(a.actor_email))}</td><td><div class="title-cell" data-open="${e(a.task_id)}">${e(a.task_title)}</div></td><td>${badge(a.action_type)}</td><td>${e(a.result||'—')}<div class="muted-note">${e(a.notes||'')}</div>${attachmentTiles((engineering.attachments||[]).filter(f=>f.activity_id===a.id||(a.comment_id&&f.comment_id===a.comment_id)),false)}</td></tr>`).join('');
 root.innerHTML=`<section class="card"><div class="card-head"><div><h2 class="card-title">Everyone’s daily work</h2><p class="card-desc">${e(dateFmt(day))} ${ui("· Shared task activity and personal daily entries")}</p></div><button class="btn tiny" data-view="daily">View Daily Work ↗</button></div><div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>ACTIVITY</th><th>RESULT</th><th>DETAILS</th></tr></thead><tbody>${personRows||`<tr><td colspan="4">${ui("No activity logged for this date.")}</td></tr>`}</tbody></table></div></section><div class="section-gap"></div><section class="card"><div class="card-head"><div><h2 class="card-title">Engineering Board progress</h2><p class="card-desc">${e(dateFmt(day))}</p></div><div><button class="btn tiny" data-view="board">Board ↗</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>TASK</th><th>ACTIVITY</th><th>UPDATE</th></tr></thead><tbody>${changes||`<tr><td colspan="4">${ui("No Engineering Board updates for this date.")}</td></tr>`}</tbody></table></div></section><div class="section-gap"></div><section class="card"><div class="card-head"><div><h2 class="card-title">Upcoming versions</h2><p class="card-desc">${ui("Expected features and fixes")}</p></div><button class="btn tiny" data-view="releases">Version Control ↗</button></div><div class="card-body">${releaseRows||empty('No upcoming versions','Engineering can create the next release plan.')}</div></section>`;
}
function parentTaskSelect(t,writable=true){return `<div class="field"><label>Parent task (optional)</label><select class="task-field" data-key="parent_task_id" ${writable&&(canQA()||canDev())?'':'disabled'}><option value="">No parent task</option>${state.tasks.filter(p=>p.id!==t.id&&(p.work_kind==='Engineering'||!p.work_kind||p.id===t.parent_task_id)).map(p=>`<option value="${e(p.id)}" ${t.parent_task_id===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</select></div>`}
async function loadBoardActivity(){const day=state.day,d=await api('/engineering-daily?date='+day);if(state.view!=='board'||day!==state.day)return;const root=$('#board-daily-results');if(!root)return;root.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>TASK</th><th>ACTIVITY</th><th>DETAILS</th></tr></thead><tbody>${d.activities.map(a=>`<tr><td>${e(who(a.actor_email))}</td><td><div class="title-cell" data-open="${e(a.task_id)}">${e(a.task_title)}</div></td><td>${badge(a.action_type)}</td><td class="work-notes">${e(a.result)}<div class="muted-note">${e(a.notes||'')}</div></td></tr>`).join('')||`<tr><td colspan="4">${ui("No board activity for this date.")}</td></tr>`}</tbody></table></div>`}
function renderPrivateWork(){const root=$('#private-work-results');if(!root)return;if(isBoss()){root.innerHTML='';return;}
 root.innerHTML=renderPrivateProjects()+`<section class="card board-card private-work-board"><div class="card-head"><div><h2 class="card-title">Daily Work Board</h2><p class="card-desc">${ui("Your ongoing tasks. Open a row to continue work or log an activity.")}</p></div></div><div class="filters private-board-filters"><input autocomplete="off" type="search" class="search" id="private-work-search" aria-label="Search private tasks or project names" placeholder="${e(tr("Search tasks or project names"))}" data-ui-placeholder="Search tasks or project names" value="${e(state.privateSearch)}"><select class="select" id="private-work-status" aria-label="Private work status">${option(['Active work','In Progress','Waiting','Completed','All work','Archived work'],state.privateStatus)}</select></div><div class="workspace-private-list" id="private-board-rows"></div></section>`;
 renderPrivateBoardRows();labelMobileTables(root);
}
function renderPrivateProjects(){
 const projects=state.privateItems.filter(i=>i.kind==='Project'&&(state.privateStatus==='Archived work'?i.archived:!i.archived)).sort((a,b)=>Number(a.status==='Completed')-Number(b.status==='Completed')||String(b.updated_at).localeCompare(String(a.updated_at)));
 if(isBoss())return '';
 const addProject=canWrite()?'<button type="button" class="project-create-link" data-private-project>+ Project</button>':'';
 if(!projects.length)return addProject?`<div class="workspace-project-create">${addProject}</div>`:'';
 return `<section class="private-projects workspace-projects"><div class="workspace-section-head"><h2 class="card-title">Projects <span class="muted-note">${projects.length}</span></h2>${addProject}</div><div class="workspace-project-grid">${projects.map(i=>{const children=state.privateItems.filter(t=>t.parent_id===i.id&&t.kind==='Task'&&!t.archived),done=children.filter(t=>t.status==='Completed').length;return `<div class="task-row workspace-project-card" data-row-private="${e(i.id)}" tabindex="0" role="button" aria-label="Open project ${e(i.title)}"><strong class="workspace-task-title">${e(i.title)}</strong><div class="workspace-task-footer">${badge(i.status)}<span class="muted-note">${ui('{done} of {total} tasks complete',{done,total:children.length})}</span></div>${children.length?`<div class="workspace-project-progress" role="progressbar" aria-label="Completed tasks" aria-valuemin="0" aria-valuemax="${children.length}" aria-valuenow="${done}"><span style="width:${done/children.length*100}%"></span></div>`:''}<span class="muted-note">Updated ${e(timeFmt(i.updated_at))}</span></div>`;}).join('')}</div></section>`;
}
function renderPrivateBoardRows(){const root=$('#private-board-rows');if(!root||isBoss())return;const q=state.privateSearch.trim().toLowerCase(),parent=i=>state.privateItems.find(p=>p.id===i.parent_id),due=i=>!!(i.status!=='Completed'&&i.recurrence_rule&&i.recurrence_rule!=='none'&&i.next_due_date<=todayDate());
 const items=state.privateItems.filter(i=>i.kind==='Task'&&(state.privateStatus==='Archived work'?i.archived:!i.archived)&&(state.privateStatus==='All work'||state.privateStatus==='Archived work'||(state.privateStatus==='Active work'?i.status!=='Completed':i.status===state.privateStatus))&&(!q||[i.title,i.description,parent(i)?.title].join(' ').toLowerCase().includes(q))).sort((a,b)=>Number(!!b.inactivity_reminder)-Number(!!a.inactivity_reminder)||Number(due(b))-Number(due(a))||Number(a.status==='Completed')-Number(b.status==='Completed')||String(b.updated_at).localeCompare(String(a.updated_at))||a.title.localeCompare(b.title));
 root.innerHTML=items.map(i=>`<div class="task-row workspace-private-task ${state.privateDetail===i.id?'selected':''}" data-row-private="${e(i.id)}" tabindex="0" role="button" aria-label="Open ${e(i.title)}"><div class="workspace-private-copy"><strong>${e(i.title)}</strong><span class="muted-note">${e(parent(i)?.title||'Standalone task')} · ${i.status==='Completed'&&i.completed_date?'Completed '+e(dateFmt(i.completed_date)):'Updated '+e(timeFmt(i.updated_at))}</span><div class="workspace-private-reminders">${inactivityReminder(i)}${recurrenceBadge(i)}</div></div>${badge(i.status)}</div>`).join('')||empty(state.privateItems.some(i=>i.kind==='Task')?'No matching tasks':'No tasks yet',state.privateItems.some(i=>i.kind==='Task')?'Try another search or status.':'Use + Activity, then choose Task to add ongoing work.');
}
function dailyActivitySection(rows,title,collapsed=false,showResults=true){
 const table=`<div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>WORK / TASK</th>${showResults?'<th>RESULT</th>':''}<th>DETAILS</th></tr></thead><tbody>${rows.map(r=>{const linkedTitle=r.item?state.privateItems.find(i=>i.id===r.item)?.title||'Private project / task':'';return `<tr class="task-row daily-activity-row" ${r.id?`data-row-office="${e(r.id)}"`:`data-row-task="${e(r.task_id)}"`} tabindex="0" role="button" aria-label="${r.id&&canWrite()&&r.person===state.user.email?'Edit':'View'} ${e(r.title)}"><td>${e(who(r.person))}</td><td>${e(r.title)}${linkedTitle&&!isBoss()&&linkedTitle!==r.title?`<div class="muted-note">${e(linkedTitle)}</div>`:''}${isBoss()?`<div class="muted-note">${r.id?'Daily Work':'Engineering'}</div>`:''}</td>${showResults?`<td>${r.task_id?badge(r.result||r.kind):'—'}</td>`:''}<td class="work-notes">${e(r.notes||'—')}${attachmentTiles(r.attachments||[],canWrite()&&r.person===state.user.email)}</td></tr>`;}).join('')||`<tr><td colspan="${showResults?4:3}">${ui("No activity logged for this date.")}</td></tr>`}</tbody></table></div>`;
 return collapsed?`<details class="card daily-shared-activity"><summary>${e(title)}</summary>${table}</details>`:`<section class="card"><div class="card-head"><h2 class="card-title">${e(title)}</h2></div>${table}</section>`;
}

