document.addEventListener('drop',ev=>{const zone=ev.target.closest('[data-evidence-input],#task-drop-zone');if(!zone)return;ev.preventDefault();zone.classList.remove('dragging');if(!canWrite())return;const files=[...(ev.dataTransfer?.files||[])];if(zone.dataset.evidenceKind==='new-task')queueEvidence(files,'new-task');else if(zone.dataset.evidenceKind?.startsWith('daily-'))queueEvidence(files,zone.dataset.evidenceKind);else if(zone.dataset.evidenceKind==='private-activity')queueEvidence(files,'private-activity');else if(zone.dataset.evidenceKind==='private-direct')busy(()=>uploadPrivateTaskImages(files));else if(!state.detail||state.detailData?.task.archived)return;else if(zone.dataset.uploadComment||zone.dataset.uploadActivity)busy(()=>uploadTaskFiles(files,zone.dataset.uploadComment?{commentId:zone.dataset.uploadComment}:{activityId:zone.dataset.uploadActivity}));else if(zone.dataset.evidenceKind)queueEvidence(files,zone.dataset.evidenceKind);else busy(()=>uploadTaskFiles(files,chosenAttachmentLink()));});
let pendingActivityFiles=[],pendingCommentFiles=[],pendingTaskField=null;
function attachmentTiles(files,writable){return files.length?`<div class="linked-attachments">${files.map(a=>`<div class="attachment-entry">${a.content_type.startsWith('image/')?`<button class="screenshot-tile" data-preview-image="${e(a.id)}" data-filename="${e(a.filename)}"><img src="/api/attachments/${e(a.id)}?preview=1" alt="${e(a.filename)}"><span>${e(a.filename)}</span></button>`:`<button class="btn tiny" data-download="${e(a.id)}" data-filename="${e(a.filename)}">${e(a.filename)}</button>`}${writable&&(a.owner_email===state.user.email||canManage())?`<button class="image-delete" data-delete-attachment="${e(a.id)}" data-filename="${e(a.filename)}">Delete</button>`:''}</div>`).join('')}</div>`:'';}
async function refreshTaskDetail({preserveWorkflow=true}={}){if(!state.detail)return;const tid=state.detail,scroll=$('#detail-panel').scrollTop;
 const draftIds=['activity-notes','activity-result','activity-date','activity-env','comment-body','task-file-target'];const drafts=draftIds.map(id=>[id,$('#'+id)?.value]);const action=document.querySelector('[data-key="activity-action"]')?.value;
 const opened=[...document.querySelectorAll('#detail-content details[open]')].map(d=>d.querySelector('summary')?.textContent);
 const changed=[...document.querySelectorAll('#detail-content .task-field')].filter(f=>Object.hasOwn(state.detailData.task,f.dataset.key)&&f.value!==(f.dataset.start??String(state.detailData.task[f.dataset.key]??''))).map(f=>[f.dataset.key,f.value]);
 const envManual=$('#activity-env')?.dataset.manual;const workflowPhase=state.detailData.workflow.phase,workflowDraft=[...document.querySelectorAll('#detail-content [data-workflow-field]')].filter(f=>!f.disabled&&f.value!==f.dataset.start).map(f=>[f.dataset.workflowField,f.value]);
 const d=await api('/tasks/'+tid);if(state.detail!==tid)return;state.tasks=state.tasks.map(t=>t.id===tid?{...t,...d.task,workflow:d.workflow}:t);state.archivedTasks=state.archivedTasks.map(t=>t.id===tid?{...t,...d.task,workflow:d.workflow}:t);renderDetail(d);
 if(preserveWorkflow&&workflowPhase===d.workflow.phase)for(const [key,value]of workflowDraft){const f=document.querySelector(`[data-workflow-field="${key}"]`);if(f)f.value=value;}
 syncWorkflowStage();syncWorkflowReview();
 for(const [id,value]of drafts){const f=$('#'+id);if(id==='activity-env'&&!envManual)continue;if(f&&value!==undefined)f.value=value;}if($('#activity-env')&&envManual)$('#activity-env').dataset.manual=envManual;
 if(action){const f=document.querySelector('[data-key="activity-action"]');if(f)f.value=action;}
 for(const [key,value]of changed){const f=document.querySelector(`#detail-content .task-field[data-key="${key}"]`);if(f&&value!==String(d.task[key]??'')){f.value=value;f.closest('.field')?.classList.add('field-edited');}}
 for(const details of document.querySelectorAll('#detail-content details'))if(opened.includes(details.querySelector('summary')?.textContent))details.open=true;$('#detail-panel').scrollTop=scroll;
}
function confirmFieldChange(field){const key=field.dataset.key,t=state.detailData?.task;if(!t||!Object.hasOwn(t,key)||field.disabled||field.value===String(t[key]??''))return;const value=field.value,old=String(t[key]??''),tid=t.id,label=field.closest('.field')?.querySelector('label')?.textContent||key;
 const display=v=>['assignee','next_action_owner'].includes(key)?(v?who(v):'Unassigned'):key==='parent_task_id'?(v?state.tasks.find(t=>t.id===v)?.title||'Parent task':'No parent task'):v||'Empty';
 pendingTaskField={cancel:()=>{field.value=old;field.closest('.field')?.classList.remove('field-edited');}};
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>Change ${e(label.toLowerCase())}?</h2><button class="close" data-close="modal">×</button></div><div class="confirm-value"><span class="muted-note">Current</span><p>${e(display(old))}</p><span class="muted-note">New</span><p>${e(display(value))}</p></div><p id="field-change-error" role="alert"></p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-field-change">Confirm & save</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#confirm-field-change').onclick=async()=>{const button=$('#confirm-field-change');button.disabled=true;try{await api('/tasks/'+tid,{method:'PATCH',body:JSON.stringify({[key]:value,activity_date:state.day})});pendingTaskField=null;closeModal();await refreshTaskDetail();showToast(label+' updated');}catch(error){const msg=$('#field-change-error');if(msg)msg.textContent=error.message;else showToast(error.message,true);}finally{button.disabled=false;}};
}
function chosenAttachmentLink(){const [type,id]=($('#task-file-target')?.value||'').split(':');return type==='activity'?{activityId:id}:type==='comment'?{commentId:id}:{};}
function queueEvidence(files,kind){if(kind==='new-task'){if(newTaskSaving)return;for(const file of files){if(file.size>8*1024*1024){showToast('Each image/file must be 8 MB or smaller',true);continue;}pendingNewTaskFiles.push(file);}updateNewTaskFileList();return;}if(kind==='private-activity'){for(const file of files){if(file.size>8*1024*1024){showToast('Each image/file must be 8 MB or smaller',true);continue;}pendingPrivateActivityFiles.push(file);}updatePrivateActivityFiles();return;}if(kind.startsWith('daily-')){const mode=kind.slice(6);for(const file of files){if(file.size>8*1024*1024){showToast('Each image/file must be 8 MB or smaller',true);continue;}pendingDailyFiles[mode].push(file);}updateDailyFileList(mode);return;}if(kind==='activity'){pendingActivityFiles.push(...files);if($('#activity-file-list'))$('#activity-file-list').textContent=pendingActivityFiles.map(f=>f.name).join(' · ');if($('#workflow-file-list'))$('#workflow-file-list').textContent=pendingActivityFiles.map(f=>f.name).join(' · ');}else{pendingCommentFiles.push(...files);if($('#comment-file-list'))$('#comment-file-list').textContent=pendingCommentFiles.map(f=>f.name).join(' · ');}}
function evidencePaste(files,target){const zone=target.closest('[data-upload-comment],[data-upload-activity]');if(zone)busy(()=>uploadTaskFiles(files,zone.dataset.uploadComment?{commentId:zone.dataset.uploadComment}:{activityId:zone.dataset.uploadActivity}));else if(target.closest('.task-log,.workflow-form'))queueEvidence(files,'activity');else if(target.closest('.reply'))queueEvidence(files,'comment');else busy(()=>uploadTaskFiles(files,chosenAttachmentLink()));}
document.addEventListener('change',ev=>{
 if(ev.target.matches('#detail-content .task-field'))confirmFieldChange(ev.target);
 if(ev.target.matches('[data-recurrence-prefix]')){const prefix=ev.target.dataset.recurrencePrefix;$('#'+prefix+'-due-field').hidden=ev.target.value==='none';}
 if(ev.target.id==='office-item'){const title=$('#office-title'),item=state.privateItems.find(i=>i.id===ev.target.value);if(title.value===title.dataset.autoTitle){title.value=item?.title||'';title.dataset.autoTitle=title.value;markSuggestedDefaults($('#modal-content'),'#office-title');}}
 if(['office-item','office-status'].includes(ev.target.id))syncOfficeRecurrence();
 if(['daily-activity-files','daily-task-files'].includes(ev.target.id)){queueEvidence([...ev.target.files],ev.target.id==='daily-task-files'?'daily-task':'daily-activity');ev.target.value='';}
 if(ev.target.id==='private-activity-files'){queueEvidence([...ev.target.files],'private-activity');ev.target.value='';}
 if(['private-activity-item','private-activity-status'].includes(ev.target.id))syncPrivateActivityCycle();
 if(['daily-task-status','daily-task-recurrence'].includes(ev.target.id))syncDailyTaskCompletionDate();
 if(ev.target.id==='new-task-files'){queueEvidence([...ev.target.files],'new-task');ev.target.value='';}
 if(ev.target.id==='private-task-files'){busy(()=>uploadPrivateTaskImages([...ev.target.files]));ev.target.value='';}
 if(ev.target.id==='activity-env')ev.target.dataset.manual='1';
 if(['workflow-files','activity-files','comment-files'].includes(ev.target.id)){queueEvidence([...ev.target.files],ev.target.id==='comment-files'?'comment':'activity');ev.target.value='';}
 if(ev.target.matches('[data-activity-files]'))busy(()=>uploadTaskFiles([...ev.target.files],{activityId:ev.target.dataset.activityFiles}));
 if(ev.target.matches('[data-comment-files]'))busy(()=>uploadTaskFiles([...ev.target.files],{commentId:ev.target.dataset.commentFiles}));
});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-delete-attachment]');if(!b)return;if(b.closest('#shared-activity-editor,#private-activity-editor')){const aid=b.dataset.deleteAttachment;b.textContent='Confirm remove';b.removeAttribute('data-delete-attachment');b.onclick=()=>busy(async()=>{b.disabled=true;await api('/attachments/'+aid,{method:'DELETE',body:JSON.stringify({confirm:true})});b.closest('.attachment-entry').remove();});return;}$('#modal-content').innerHTML=`<div class="modal-head"><h2>Delete image / file?</h2><button class="close" data-close="modal">×</button></div><p>${e(b.dataset.filename)}</p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-attachment-delete">Delete</button></div>`;$('#modal-shade').classList.remove('hidden');$('#confirm-attachment-delete').onclick=()=>busy(async()=>{await api('/attachments/'+b.dataset.deleteAttachment,{method:'DELETE',body:JSON.stringify({confirm:true})});closeModal();if(state.detail)await refreshTaskDetail();if(state.view==='daily')await loadDaily();if(state.privateDetail)await refreshPrivateDetail();showToast('File deleted')});});

function confirmWorkflow(action){const t=state.detailData.task;const body={action,confirm:true,expected_revision:t.workflow_revision,activity_date:new Date().toLocaleDateString('en-CA',{timeZone:'America/Los_Angeles'})};
 for(const f of document.querySelectorAll('[data-workflow-field]'))if(!f.disabled)body[f.dataset.workflowField]=f.value;
 if(t.delivery_reset_required&&['progress','stage'].includes(action)&&(!body.estimated_delivery_date||body.estimated_delivery_date<todayDate())){document.querySelector('[data-workflow-field="estimated_delivery_date"]')?.focus();showToast('Choose a new Engineering estimated delivery date of today or later',true);return;}
 if(action==='stage'&&!body.qa_owner){const qa=document.querySelector('[data-workflow-field="qa_owner"]');qa?.focus();showToast('Choose a QA owner for the merge-to-Stage handoff',true);return;}
 const labels={close:'Complete this task',review:t.pm_owner?(body.feasibility==='Confirmed'?'Confirm review & start Engineering':'Return to PM'):'Confirm engineer review',progress:'Update engineering stage',stage:'Confirm merged to Stage and hand off to QA',qa:'Confirm Stage test result',production:'Confirm this change is on Production'};
 const effect=action==='close'?ui('Mark this task complete. Your completion update is recorded under {actor}; the Assignee stays {assignee}.',{actor:who(state.user.email),assignee:who(t.assignee)}):action==='review'?(body.feasibility==='Confirmed'?ui('Engineering starts. Estimated delivery: {date}.',{date:dateFmt(body.estimated_delivery_date)}):t.pm_owner?ui('This task returns to PM with your explanation. PM must update the design and resubmit Handoff before Engineering continues.'):ui('The request stays on hold until the scope is clarified and reviewed again.')):action==='stage'?ui('This build is merged to Stage and available for testing. Next owner: {owner} (QA). QA testing starts after this confirmation.',{owner:who(body.qa_owner)}):action==='qa'?ui(body.qa_status==='Passed'?'QA passed. The engineer can deploy this Stage build to Production.':'Return to Engineering. QA waits until the fixed build is confirmed on Stage again.'):action==='production'?ui('Mark On Production and automatically include it in the pending version update.'):ui('Engineering stage: {stage}. QA continues to wait for Stage confirmation.',{stage:body.development_status});
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${e(labels[action])}?</h2><button class="close" data-close="modal">×</button></div><p>${effect}</p>${action==='qa'?`<p>${badge(body.qa_status)}</p>`:''}<p id="workflow-error" role="alert"></p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-workflow">Confirm</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#confirm-workflow').onclick=async()=>{const button=$('#confirm-workflow');button.disabled=true;try{
  const result=await api('/tasks/'+t.id+'/workflow',{method:'POST',body:JSON.stringify(body)});closeModal();
  let failed=false;for(const file of [...pendingActivityFiles]){const form=new FormData();form.append('file',file);form.append('task_id',t.id);form.append('activity_id',result.id);try{await api('/attachments',{method:'POST',body:form});pendingActivityFiles.splice(pendingActivityFiles.indexOf(file),1);}catch{failed=true;}}
  if(state.detail===t.id)await refreshTaskDetail({preserveWorkflow:false});
  const [summary,history]=await Promise.all([api('/summary?date='+state.day),canManage()?api('/activity'):Promise.resolve({activities:[]})]);state.summary=summary;state.activities=history.activities;render();
  showToast(failed?'Step saved. Some images failed to upload; retry from Images for this step.':'Next step updated',failed);
 }catch(error){const field=$('#workflow-error');if(field){field.textContent=error.message;if(error.status===409){const refresh=document.createElement('button');refresh.className='btn';refresh.textContent='Refresh task';refresh.onclick=()=>busy(async()=>{closeModal();await refreshTaskDetail()});field.appendChild(refresh);}}else showToast(error.message,true);}finally{button.disabled=false;}};
}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-workflow-action]');if(b)confirmWorkflow(b.dataset.workflowAction);});

const todayDate=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Los_Angeles'});
function recurrenceFields(prefix,item={}){const rule=item.recurrence_rule||'none';return `<section class="repeat-settings"><h3 class="card-title">Repeat / reminders</h3><div class="form-row"><div class="field"><label>Repeat</label><select id="${prefix}-recurrence" data-recurrence-prefix="${prefix}">${['none','daily','weekly','monthly'].map(r=>`<option value="${r}" ${r===rule?'selected':''}>${{none:'Does not repeat',daily:'Daily',weekly:'Weekly',monthly:'Monthly'}[r]}</option>`).join('')}</select></div><div class="field" id="${prefix}-due-field" ${rule==='none'?'hidden':''}><label>${item.next_due_date?'Next due date':'First due date'}</label><input autocomplete="off" id="${prefix}-due" type="date" value="${e(item.next_due_date||state.day)}"></div></div><p class="muted-note">${ui("Due reminders continue until you complete the occurrence. Only actual activities count as daily work.")}</p></section>`;}
function readRecurrence(prefix){const rule=$('#'+prefix+'-recurrence').value;return {recurrence_rule:rule,next_due_date:rule==='none'?'':$('#'+prefix+'-due').value};}
function recurrenceBadge(i){if(!i.recurrence_rule||i.recurrence_rule==='none')return '';const due=i.next_due_date,today=todayDate();return `<span class="recurrence-note">${e({daily:'Daily',weekly:'Weekly',monthly:'Monthly'}[i.recurrence_rule])} · ${i.status!=='Completed'&&due<=today?badge(due<today?'Overdue':'Due today')+' ':''}${e(dateFmt(due))}</span>`;}
function completeTaskControl(prefix){return `<div class="complete-task-control" id="${prefix}-complete-task-control" hidden><label class="completion-choice"><input autocomplete="off" type="checkbox" id="${prefix}-complete-task"><span class="completion-choice-mark" aria-hidden="true">✓</span><span>${ui('Complete task')}</span></label><p class="muted-note" id="${prefix}-complete-task-note">${ui('Check when the whole task is finished. Otherwise, just record your progress.')}</p></div>`;}
function syncCompleteTaskControl(prefix,item,status){const control=$('#'+prefix+'-complete-task-control');if(!control)return;if(control.dataset.itemId!==(item?.id||''))$('#'+prefix+'-complete-task').checked=false;control.dataset.itemId=item?.id||'';control.hidden=!(item?.kind==='Task'&&!item.archived&&item.status!=='Completed'&&(!item.recurrence_rule||item.recurrence_rule==='none'));if(control.hidden)$('#'+prefix+'-complete-task').checked=false;systemText($('#'+prefix+'-complete-task-note'),'Check when the whole task is finished. Otherwise, just record your progress.');}
function syncOfficeRecurrence(){const timeField=$('#office-minutes-field');if(timeField)timeField.hidden=state.privateItems.find(i=>i.id===$('#office-item')?.value)?.kind==='Task';syncCompleteTaskControl('office',state.privateItems.find(i=>i.id===$('#office-item')?.value),$('#office-status')?.value);const control=$('#office-recurrence-controls');if(!control)return;const item=state.privateItems.find(i=>i.id===$('#office-item').value),recurring=item&&item.recurrence_rule&&item.recurrence_rule!=='none'&&item.status!=='Completed';control.hidden=!recurring;if(recurring){$('#office-complete-cycle').checked=false;systemText($('#office-cycle-info'),'Due {date}. Partial or blocked work counts today; the due reminder stays until this occurrence is completed.',{date:dateFmt(item.next_due_date)});}}
function updateDailyFileList(mode){const list=$('#daily-'+mode+'-file-list');if(list)list.innerHTML=pendingDailyFiles[mode].map((f,index)=>`<span class="pending-daily-image">${e(f.name)} <button type="button" data-daily-file-remove="${index}" data-daily-file-mode="${mode}" aria-label="Remove ${e(f.name)}">×</button></span>`).join('');}
async function saveDailyImages(files,target){let failed=false;for(const file of [...files]){const form=new FormData();form.append('file',file);for(const [key,value]of Object.entries(target))form.append(key,value);try{await api('/attachments',{method:'POST',body:form});files.splice(files.indexOf(file),1);}catch{failed=true;}}updateDailyFileList(target.office_id?'activity':'task');return failed;}
async function uploadPrivateTaskImages(files){const tid=state.privateDetail;if(!tid||!canWrite()||state.privateDetailData?.item.owner_email!==state.user.email)return;for(const file of files){const f=new FormData();f.append('file',file);f.append('private_work_id',tid);await api('/attachments',{method:'POST',body:f});}await refreshPrivateDetail();if(state.view==='daily')await loadDaily();}
async function openPrivateDetail(iid,discard=false){if(!discard&&hasDirtyTask())return askDiscardTask(()=>openPrivateDetail(iid,true));state.detail=null;state.detailData=null;pendingActivityFiles=[];pendingCommentFiles=[];pendingPrivateActivityFiles=[];state.privateDetail=iid;const request=++detailRequest;$('#panel-shade').classList.remove('hidden');$('#detail-panel').classList.remove('hidden');$('#detail-content').innerHTML=`<div class="panel-header">${ui("Loading private work…")}<button class="close" data-close="detail">×</button></div>`;const d=await api('/private-work/'+iid);if(request!==detailRequest||state.privateDetail!==iid)return;state.privateItems=[...state.privateItems.filter(i=>i.id!==iid),d.item];renderPrivateDetail(d);$('#detail-panel').scrollTop=0;}
async function refreshPrivateDetail(){const iid=state.privateDetail;if(!iid)return;const d=await api('/private-work/'+iid);if(state.privateDetail!==iid)return;state.privateItems=[...state.privateItems.filter(i=>i.id!==iid),d.item];const opened=[...document.querySelectorAll('[data-private-section][open]')].map(el=>el.dataset.privateSection),scroll=$('#detail-panel').scrollTop,draft=['private-activity-item','private-activity-details','private-activity-date','private-activity-status'].map(id=>[id,$('#'+id)?.value,$('#'+id)?.hasAttribute('data-suggested')]),savedId=$('#private-activity-form')?.dataset.savedId,completed=$('#private-activity-complete-cycle')?.checked,completeTask=$('#private-activity-complete-task')?.checked;renderPrivateDetail(d);for(const [id,value,suggested]of draft)if($('#'+id)&&value!==undefined){const field=$('#'+id);if(id==='private-activity-item'&&savedId&&field.tagName==='SELECT'&&![...field.options].some(o=>o.value===value)){const child=d.children?.find(t=>t.id===value);if(child)field.add(new Option('Task · '+child.title+' · Completed',value));}field.value=value;if(!suggested)clearSuggestedValue(field);}syncPrivateActivityCycle();if($('#private-activity-complete-cycle'))$('#private-activity-complete-cycle').checked=!!completed;if($('#private-activity-complete-task')&&!$('#private-activity-complete-task-control').hidden)$('#private-activity-complete-task').checked=!!completeTask;if(savedId&&$('#private-activity-form')){$('#private-activity-form').dataset.savedId=savedId;$('#private-activity-item').disabled=true;}for(const el of document.querySelectorAll('[data-private-section]'))el.open=opened.includes(el.dataset.privateSection);updatePrivateActivityFiles();$('#detail-panel').scrollTop=scroll;}
let pendingPrivateActivityFiles=[];
function privateActivityComposer(i,children=[]){
 const recurring=i.recurrence_rule&&i.recurrence_rule!=='none'&&i.status!=='Completed';
 return `<section class="private-activity-composer"><h3 class="card-title">Add activity</h3><form autocomplete="off" id="private-activity-form" data-work-id="${e(i.id)}"><p class="muted-note">${ui("Record what you did. This update counts toward the selected day’s work.")}</p>${i.kind==='Project'?`<div class="field"><label for="private-activity-item">Activity belongs to</label><select id="private-activity-item"><option value="${e(i.id)}">Project itself</option>${children.filter(t=>!t.archived&&t.status!=='Completed').map(t=>`<option value="${e(t.id)}">Task · ${e(t.title)}</option>`).join('')}</select></div>`:`<input autocomplete="off" id="private-activity-item" type="hidden" value="${e(i.id)}">`}<div class="field"><label for="private-activity-details">${ui("What did you do?")}</label><textarea autocomplete="off" id="private-activity-details" placeholder="${e(tr("e.g. Finished the first draft. Waiting for feedback."))}" data-ui-placeholder="e.g. Finished the first draft. Waiting for feedback." required></textarea></div><div class="form-row"><div class="field"><label for="private-activity-date">Work date</label><input autocomplete="off" id="private-activity-date" data-suggested="true" class="suggested-value" type="date" value="${state.day}" required></div><input autocomplete="off" type="hidden" id="private-activity-status" value=""></div><div id="private-activity-cycle" ${recurring?'':'hidden'}><label class="completion-choice"><input autocomplete="off" id="private-activity-complete-cycle" type="checkbox"><span class="completion-choice-mark" aria-hidden="true">✓</span><span>${ui("Complete this occurrence")}</span></label><p class="muted-note">${ui("Partial work keeps the reminder. Completing this occurrence advances the next due date.")}</p></div>${completeTaskControl('private-activity')}${evidencePicker('private-activity-files','private-activity','Images for this activity')}<p id="private-activity-error" role="alert"></p><div class="form-actions"><button class="btn primary" type="submit">Save activity</button></div></form></section>`;
}
async function savePrivateActivity(form){
 const button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;
 try{const id=$('#private-activity-item').value,item=state.privateItems.find(t=>t.id===id)||state.privateDetailData.children?.find(t=>t.id===id),body={title:item?.title||state.privateDetailData.item.title,work_item_id:id,work_date:$('#private-activity-date').value,status:$('#private-activity-status').value,category:'Work',minutes:Number($('#private-activity-minutes')?.value||0),details:$('#private-activity-details').value};
 body.complete_task=!!$('#private-activity-complete-task')?.checked;
 if(!$('#private-activity-cycle').hidden)body.complete_occurrence=$('#private-activity-complete-cycle').checked;
 if(body.complete_task||body.complete_occurrence)body.status='Completed';
 const result=await api('/office'+(form.dataset.savedId?'/'+form.dataset.savedId:''),{method:form.dataset.savedId?'PATCH':'POST',body:JSON.stringify(body)});form.dataset.savedId=result.id;$('#private-activity-item').disabled=true;
 let failed=false;for(const file of [...pendingPrivateActivityFiles]){const upload=new FormData();upload.append('file',file);upload.append('office_id',result.id);try{await api('/attachments',{method:'POST',body:upload});pendingPrivateActivityFiles.splice(pendingPrivateActivityFiles.indexOf(file),1);}catch{failed=true;}}
 if(failed){updatePrivateActivityFiles();systemText($('#private-activity-error'),'Activity saved. Some images failed to upload; save again to retry without creating another entry.');return;}
 pendingPrivateActivityFiles=[];if($('#private-activity-complete-task'))$('#private-activity-complete-task').checked=false;$('#private-activity-details').value='';delete form.dataset.savedId;$('#private-activity-item').disabled=false;await reload();showToast('Activity saved');
 }catch(error){$('#private-activity-error').textContent=error.message;}finally{button.disabled=false;}
}
function updatePrivateActivityFiles(){const list=$('#private-activity-file-list');if(list)list.innerHTML=pendingPrivateActivityFiles.map((f,n)=>`<span class="pending-daily-image">${e(f.name)} <button type="button" data-private-file-remove="${n}" aria-label="Remove ${e(f.name)}">×</button></span>`).join('');}
function syncPrivateActivityCycle(){const selected=$('#private-activity-item')?.value,item=state.privateItems.find(i=>i.id===selected)||state.privateDetailData?.children?.find(i=>i.id===selected),cycle=$('#private-activity-cycle');syncCompleteTaskControl('private-activity',item,$('#private-activity-status')?.value);if(cycle){cycle.hidden=!(item&&item.recurrence_rule&&item.recurrence_rule!=='none'&&item.status!=='Completed');$('#private-activity-complete-cycle').checked=false;}}
document.addEventListener('submit',ev=>{if(ev.target.id==='private-activity-form'){ev.preventDefault();savePrivateActivity(ev.target);}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-private-file-remove]');if(b){pendingPrivateActivityFiles.splice(Number(b.dataset.privateFileRemove),1);updatePrivateActivityFiles();}});
function completionDateRow(item,writable,shared=false){const repeating=!shared&&item.recurrence_rule&&item.recurrence_rule!=='none',complete=shared?item.development_status==='Closed':item.status==='Completed';if(!complete&&!(repeating&&item.completed_date))return '';return `<div class="completion-date-row"><span class="muted-note">${repeating?'Last completed':'Completed date'}</span>${writable?`<button type="button" class="account-link" data-completion-date="${shared?'engineering':'private'}">${item.completed_date?e(dateFmt(item.completed_date)):'Set date'}</button>`:`<span>${item.completed_date?e(dateFmt(item.completed_date)):'Not set'}</span>`}</div>`;}
function editCompletionDate(shared=false){const item=shared?state.detailData?.task:state.privateDetailData?.item;if(!item||item.archived||(shared?!canDev():!canWrite()||item.owner_email!==state.user.email))return;
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${ui('Update completion date')}</h2><button class="close" data-close="modal">×</button></div><p>${e(item.title)}</p><div class="field"><label for="task-completed-date">Completed date *</label><input autocomplete="off" id="task-completed-date" type="date" value="${e(item.completed_date||todayDate())}"></div><p class="muted-note">${ui('This date belongs to the task. Activity work dates stay separate.')}</p><p id="completed-date-error" role="alert"></p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="save-completed-date">Save date</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#save-completed-date').onclick=async()=>{const button=$('#save-completed-date');button.disabled=true;try{await api((shared?'/tasks/':'/private-work/')+item.id,{method:'PATCH',body:JSON.stringify({completed_date:$('#task-completed-date').value})});closeModal();if(shared)await refreshTaskDetail();else await refreshPrivateDetail();if(state.view==='daily')await loadDaily();showToast('Completion date updated');}catch(error){systemText($('#completed-date-error'),error.message);}finally{button.disabled=false;}};
}
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-completion-date]');if(button)editCompletionDate(button.dataset.completionDate==='engineering');});
function privateTaskStatusTag(i,writable){if(!writable)return badge(i.status);return `<span class="private-status-control"><button type="button" class="private-status-tag" data-private-status-trigger aria-label="Change ${e(i.kind.toLowerCase())} status, currently ${e(i.status)}" aria-expanded="false">${badge(i.status)}</button><span class="private-status-options" id="private-status-options" hidden>${['In Progress','Waiting','Completed'].map(status=>`<button type="button" class="btn tiny" data-private-status-value="${e(status)}" ${status===i.status?'disabled':''}>${status==='Completed'&&i.recurrence_rule&&i.recurrence_rule!=='none'?'Complete this occurrence':e(status)}</button>`).join('')}</span></span>`;}
function confirmPrivateTaskStatus(status){const i=state.privateDetailData?.item;if(!i||!['Task','Project'].includes(i.kind)||i.archived||!canWrite()||i.owner_email!==state.user.email||!['In Progress','Waiting','Completed'].includes(status)||status===i.status)return;
 const recurring=i.kind==='Task'&&i.recurrence_rule&&i.recurrence_rule!=='none';
 $('#private-status-options').hidden=true;document.querySelector('[data-private-status-trigger]').setAttribute('aria-expanded','false');
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${recurring&&status==='Completed'?'Complete this occurrence?':'Change '+e(i.kind.toLowerCase())+' status?'}</h2><button class="close" data-close="modal">×</button></div><p>${e(i.title)}</p><p>${badge(i.status)} → ${badge(status)}</p>${status==='Completed'?`<div class="field"><label for="private-status-completed-date">Completed date *</label><input autocomplete="off" id="private-status-completed-date" type="date" value="${todayDate()}"></div>${recurring?`<p class="muted-note">${ui("Only this occurrence is completed. The next repeat stays active.")}</p>`:''}`:''}<p id="private-status-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close="modal">Cancel</button><button type="button" class="btn primary" id="confirm-private-status" data-target-status="${e(status)}">${status==='Completed'?'Confirm completion':'Confirm status'}</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#confirm-private-status').onclick=async()=>{const button=$('#confirm-private-status');button.disabled=true;try{await api('/private-work/'+i.id,{method:'PATCH',body:JSON.stringify({status,...(status==='Completed'?{completed_date:$('#private-status-completed-date').value}:{}),...(recurring&&status==='Completed'?{expected_due_date:i.next_due_date}:{})})});closeModal();await reload();showToast(recurring&&status==='Completed'?'Occurrence completed; next repeat remains active':i.kind+' status updated');}catch(error){if($('#private-status-error'))$('#private-status-error').textContent=error.message;else showToast(error.message,true);}finally{button.disabled=false;}};
}
document.addEventListener('click',ev=>{const trigger=ev.target.closest('[data-private-status-trigger]');if(trigger){const menu=$('#private-status-options');menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));return;}const choice=ev.target.closest('[data-private-status-value]');if(choice)confirmPrivateTaskStatus(choice.dataset.privateStatusValue);});
function renderPrivateDetail(d){
 state.privateDetailData=d;const i=d.item,owned=canWrite()&&i.owner_email===state.user.email,writable=owned&&!i.archived,project=i.kind==='Project',children=d.children||[],noun=project?'project':'task';
 $('#detail-content').innerHTML=`<div class="panel-header"><span class="panel-kicker">PRIVATE ${e(i.kind.toUpperCase())} · ${e(who(i.owner_email))}</span><button class="close" data-close="detail">×</button></div><div class="panel-body task-focus"><h2 class="detail-heading">${e(i.title)}</h2>${instructionFor(project?"private-project":"private-task")}${project?'':'<h3 class="card-title">Task overview</h3>'}<div class="private-overview-status">${privateTaskStatusTag(i,writable)} ${i.archived?badge('Archived'):recurrenceBadge(i)}</div>${completionDateRow(i,writable)}${inactivityReminder(i)}${i.description?`<p class="work-notes">${e(i.description)}</p>`:''}${writable?`<div class="form-actions"><button class="btn" data-private-edit="${e(i.id)}">Edit ${noun}</button></div>`:owned&&i.archived?`<div class="form-actions"><button class="btn" data-private-restore="${e(i.id)}">Restore ${noun}</button></div>`:''}${project?projectTaskList(children,writable,i.id):''}${writable?privateActivityComposer(i,children):''}<section id="private-task-evidence"><h3 class="card-title">${project?'Project':'Task'} attachments</h3><p class="muted-note">${ui(project?'Project reference files, such as requirements and design mockups.':'Reference images and files for this task.')} ${ui("Add screenshots of daily progress to the corresponding activity.")}</p>${attachmentTiles(d.attachments.filter(a=>a.private_work_id===i.id),writable&&!project)}${writable&&!project?evidencePicker('private-task-files','private-direct','Add task attachments'):''}</section>${project?'<section class="private-activity-timeline"><h3 class="card-title">Activity timeline</h3>':'<details class="task-secondary private-activity-timeline" data-private-section="history"><summary>Activity history</summary>'}<p class="muted-note">${ui(project?'Daily progress for this project and its tasks.':'Continue this task across days.')} ${ui("Each entry records the work date, details and attachments.")}</p>${d.activities.map(a=>`<div class="timeline-item"><div class="timeline-top"><span>${e(dateFmt(a.work_date))} · ${e(who(a.owner_email))}</span></div>${project?`<p class="muted-note">${a.work_item_id===i.id?'Project itself':`Task · ${e(children.find(t=>t.id===a.work_item_id)?.title||a.title)}`}</p>`:''}<p><strong>${e(a.title)}</strong></p>${a.details?`<p class="work-notes">${e(a.details)}</p>`:''}${attachmentTiles(d.attachments.filter(f=>f.office_id===a.id),writable)}${writable?`<button class="account-link" data-office-edit="${e(a.id)}">Edit activity / add images</button>`:''}</div>`).join('')||empty('No activity yet','Add an activity whenever you work on this '+noun+'.')}${project?'</section>':'</details>'}</div>`;
 if(writable){syncPrivateActivityCycle();updatePrivateActivityFiles();}
}
function inactivityReminder(i){const r=i.inactivity_reminder;if(!r)return '';return `<span class="recurrence-note">${badge('Update needed')} ${ui('No activity for {days} working days · Log progress or update the task status.',{days:r.business_days})}</span>`;}
function renderPersonalReminders(items){if(isBoss()||!items.length)return '';return `<section class="card personal-reminders"><div class="card-head"><h2 class="card-title">Daily Work reminders</h2><p class="card-desc">${ui("Due tasks and work that needs a progress update.")}</p></div><div class="card-body">${items.map(i=>`<div class="list-row"><div><button class="private-work-title" data-private-open="${e(i.id)}">${e(i.title)}</button>${inactivityReminder(i)}${recurrenceBadge(i)}</div></div>`).join('')}</div></section>`;}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-daily-file-remove]');if(b){pendingDailyFiles[b.dataset.dailyFileMode].splice(Number(b.dataset.dailyFileRemove),1);updateDailyFileList(b.dataset.dailyFileMode);}});

function confirmArchive(path,restore=false){const action=restore?'Restore':'Archive';$('#modal-content').innerHTML=`<div class="modal-head"><h2>${action} this work?</h2><button class="close" data-close="modal">×</button></div><p>${ui(restore?'Return this item to active work.':'Keep its activity and attachments, and move it out of active work.')}${path.startsWith('/private-work/')&&state.privateDetailData?.item.kind==='Project'?' Child tasks keep their individual state.':''}</p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-archive">${action}</button></div>`;$('#modal-shade').classList.remove('hidden');$('#confirm-archive').onclick=()=>busy(async()=>{await api(path+(restore?'/restore':'/archive'),{method:'POST',body:JSON.stringify({confirm:true})});closeModal();if(state.privateDetail||state.detail)closeDetail(true);await reload();showToast(restore?'Work restored':'Work archived');});}

let avatarSaving=false;
async function prepareAvatarPhoto(file){if(!file||!file.size||file.size>8*1024*1024)throw new Error('Choose a photo up to 8 MB');if(file.type==='image/svg+xml'||!/\.(png|jpe?g|webp|gif)$/i.test(file.name)&&!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw new Error('Choose a PNG, JPG, WebP or GIF image');
 const url=URL.createObjectURL(file);try{const photo=new Image();await new Promise((resolve,reject)=>{photo.onload=resolve;photo.onerror=()=>reject(new Error('This photo could not be opened. Choose another image.'));photo.src=url;});const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const side=Math.min(photo.naturalWidth,photo.naturalHeight);canvas.getContext('2d').drawImage(photo,(photo.naturalWidth-side)/2,(photo.naturalHeight-side)/2,side,side,0,0,256,256);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.9));if(!blob)throw new Error('This photo could not be opened. Choose another image.');return new File([blob],'avatar.'+(blob.type==='image/webp'?'webp':'png'),{type:blob.type});}finally{URL.revokeObjectURL(url);}
}
async function saveAccountAvatar(file,remove=false){if(avatarSaving||!state.user)return;avatarSaving=true;const email=state.user.email;for(const button of document.querySelectorAll('#account-avatar-settings button'))button.disabled=true;systemText($('#avatar-upload-error'),'');systemText($('#avatar-upload-status'),remove?'Removing photo…':'Uploading photo…');
 try{let result;if(remove)result=await api('/avatar',{method:'DELETE'});else{const photo=await prepareAvatarPhoto(file),form=new FormData();form.append('file',photo);result=await api('/avatar',{method:'POST',body:form});}if(state.user?.email!==email)return;state.user.avatar_id=result.avatar_id;const member=state.users.find(u=>u.email===email);if(member)member.avatar_id=result.avatar_id;updateProfileAvatars();const removeButton=$('#account-remove-avatar');if(removeButton)removeButton.hidden=!result.avatar_id;systemText($('#avatar-upload-status'),remove?'Photo removed':'Photo updated');showToast(remove?'Photo removed':'Photo updated');}catch(error){systemText($('#avatar-upload-status'),'');systemText($('#avatar-upload-error'),error.message);showToast(error.message,true);}finally{avatarSaving=false;for(const button of document.querySelectorAll('#account-avatar-settings button'))button.disabled=false;}
}
function accountMenu(){if(!state.user)return;$('#modal-content').classList.remove('image-preview','task-create-modal');$('#modal-content').innerHTML=`<div class="modal-head"><h2>My account</h2><button class="close" data-close="modal">×</button></div><div class="account-profile-summary">${avatarHtml(state.user.email,'account-avatar')}<div><strong>${e(state.user.display_name||who(state.user.email))}</strong><p class="muted-note">${e(state.user.email)}</p></div></div>${instructionFor('account-avatar')}<section id="account-avatar-settings"><h3 class="card-title">Profile photo</h3><button type="button" class="task-drop-zone account-avatar-drop" data-avatar-upload ${avatarSaving?'disabled':''}><span>${ui('Tap or click to choose a photo, or drop it here.')}</span></button><input autocomplete="off" type="file" id="account-avatar-file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><p class="muted-note">${ui('PNG, JPG, WebP or GIF, up to 8 MB. You can also paste an image with Ctrl/Cmd + V.')}</p><button type="button" class="account-link danger-link" id="account-remove-avatar" ${state.user.avatar_id?'':'hidden'}>Remove photo</button><p id="avatar-upload-status" class="muted-note" role="status"></p><p id="avatar-upload-error" class="danger-link" role="alert"></p></section><div class="form-actions"><button type="button" class="btn" id="account-change-password">Change password</button><button type="button" class="btn" id="account-sign-out">Sign out</button></div>`;$('#modal-shade').classList.remove('hidden');$('#account-change-password').onclick=()=>passwordModal();$('#account-sign-out').onclick=()=>busy(async()=>{await api('/auth/logout',{method:'POST'});closeModal();await showLogin();});$('#account-remove-avatar').onclick=()=>busy(()=>saveAccountAvatar(null,true));}
document.addEventListener('click',ev=>{if(ev.target.closest('[data-avatar-upload]'))$('#account-avatar-file')?.click();});
document.addEventListener('change',ev=>{if(ev.target.id==='account-avatar-file'){const file=ev.target.files[0];ev.target.value='';if(file)busy(()=>saveAccountAvatar(file));}});
document.addEventListener('dragover',ev=>{const zone=ev.target.closest('[data-avatar-upload]');if(zone){ev.preventDefault();zone.classList.add('dragging');}});
document.addEventListener('dragleave',ev=>{const zone=ev.target.closest('[data-avatar-upload]');if(zone)zone.classList.remove('dragging');});
document.addEventListener('drop',ev=>{const zone=ev.target.closest('[data-avatar-upload]');if(!zone)return;ev.preventDefault();zone.classList.remove('dragging');const file=ev.dataTransfer?.files?.[0];if(file)busy(()=>saveAccountAvatar(file));});
$('#avatar').onclick=accountMenu;
$('#account-menu').onclick=accountMenu;
$('#usage-guide').onclick=usageGuide;

const pmCategories=['New Feature Requirements','Improvements','Product Design','Report Design','Business Logic Design','Requirement Research','Engineering Coordination','Feature Planning'];
function workOwnerOptions(kind,value=''){return kind==='Quick Task'?memberOptions(value):workflowMemberOptions(kind==='PM Task'?'PM':'Engineering',value);}
function collaboratorPicker(t,enabled){
 const selected=JSON.parse(t.collaborators_json||'[]'),members=state.users.filter(u=>u.enabled&&JSON.parse(u.groups_json||'[]').includes('Engineering'));
 for(const email of selected)if(!members.some(u=>u.email===email))members.push({email,enabled:0});
 return `<div class="field collaborator-picker"><label>Collaborators</label><button type="button" class="collaborator-trigger" aria-expanded="false" aria-controls="collaborator-popup" data-collaborator-toggle><span data-collaborator-caption>${selected.length?e(selected.length===1?who(selected[0]):'Selected engineers'):'Select engineers'}</span><span class="collaborator-count" data-collaborator-count ${selected.length?'':'hidden'}>${selected.length}</span><span aria-hidden="true">⌄</span></button><div class="collaborator-popup" id="collaborator-popup" hidden><input autocomplete="off" type="search" class="collaborator-search" data-collaborator-search aria-label="Search engineers" placeholder="${e(tr('Search engineers'))}" data-ui-placeholder="Search engineers"><div class="collaborator-options">${members.map(u=>`<label class="collaborator-option" data-collaborator-option data-search="${e((who(u.email)+' '+u.email).toLowerCase())}"><input autocomplete="off" type="checkbox" name="tracking-collaborator" value="${e(u.email)}" ${selected.includes(u.email)?'checked':''} ${enabled&&u.enabled?'':'disabled'}><span>${e(who(u.email))}${u.enabled?'':` <small>${ui('Unavailable')}</small>`}</span></label>`).join('')}</div><p class="collaborator-empty" hidden>${ui('No matching engineers.')}</p></div></div>`;
}
function closeCollaboratorPicker(restoreFocus=false){const popup=$('#collaborator-popup'),trigger=document.querySelector('[data-collaborator-toggle]');if(!popup)return;popup.hidden=true;trigger?.setAttribute('aria-expanded','false');if(restoreFocus)trigger?.focus();}
document.addEventListener('click',ev=>{const trigger=ev.target.closest('[data-collaborator-toggle]');if(trigger){const popup=$('#collaborator-popup');popup.hidden=!popup.hidden;trigger.setAttribute('aria-expanded',String(!popup.hidden));if(!popup.hidden)popup.querySelector('input[type="search"]').focus();}else if(!ev.target.closest('.collaborator-picker'))closeCollaboratorPicker();});
document.addEventListener('input',ev=>{if(!ev.target.matches('[data-collaborator-search]'))return;const search=ev.target.value.toLowerCase().trim(),rows=[...document.querySelectorAll('[data-collaborator-option]')];for(const row of rows)row.hidden=!row.dataset.search.includes(search);const empty=$('.collaborator-empty');if(empty)empty.hidden=rows.some(row=>!row.hidden);});
document.addEventListener('change',ev=>{if(ev.target.name!=='tracking-collaborator')return;const selected=[...document.querySelectorAll('[name="tracking-collaborator"]:checked')],caption=$('[data-collaborator-caption]'),count=$('[data-collaborator-count]');if(caption)caption.textContent=selected.length?(selected.length===1?who(selected[0].value):'Selected engineers'):'Select engineers';if(count){count.textContent=selected.length;count.hidden=!selected.length;}});
function trackingOverview(d,writable){
 const t=d.task,me=state.user.email,simple=t.work_kind==='Quick Task'||t.work_kind==='PM Task'&&t.pm_stage!=='Implementation',owner=canManage()||[t.primary_owner,t.assignee,...JSON.parse(t.collaborators_json||'[]')].includes(me),editable=writable&&(owner||canQA()||state.user.groups.includes('PM'));
 const field=(label,id,value,type='text')=>`<div class="field"><label>${e(label)}</label><input autocomplete="off" id="tracking-${id}" type="${type}" value="${e(value||'')}" ${editable&&(id!=='qa-due'||canQA()&&d.workflow.phase==='qa')&&(id!=='delivery'||owner&&d.workflow.phase==='development'&&!t.delivery_reset_required)?'':'disabled'}></div>`;
 const collaborators=JSON.parse(t.collaborators_json||'[]');
 const dates=`<p class="muted-note">Original Engineering estimate: ${e(dateFmt(t.original_delivery_date))} · Engineering completed: ${e(dateFmt(t.engineering_completed_date))} · QA completed: ${e(dateFmt(t.qa_completed_date))} · Final completion: ${e(dateFmt(t.completed_date))}</p>`;
 return `<section class="tracking-section"><h3 class="card-title">Work tracking</h3>${t.follow_up?`<p>${badge(t.follow_up.status)}${t.follow_up.overdue?' '+badge('Overdue'):''}</p>`:''}${t.delivery_reset_required?`<p role="alert">${ui('Set a new Engineering delivery date before sending the fixed build to QA.')}</p>`:''}<div class="form-row"><div class="field"><label>Planning status</label><select id="tracking-planning" ${editable&&t.development_status!=='Closed'?'':'disabled'}>${option(t.development_status==='Closed'?['Completed']:['Backlog','Planned','Active'],t.planning_status)}</select></div>${simple?`<div class="field"><label>Status</label><select id="tracking-status" ${writable&&owner?'':'disabled'}>${option(['To Do','In Progress','Completed'],t.work_status)}</select></div>${field('Completed Date','completed',t.completed_date,'date')}`:field(d.workflow.phase==='development'&&!t.delivery_reset_required?'Engineering estimated delivery':'Last Engineering estimate (reference)','delivery',t.estimated_delivery_date,'date')+field(d.workflow.phase==='qa'?'QA due date':'QA round due (reference)','qa-due',t.qa_due_date,'date')}</div>${simple?`<div class="form-row"><div class="field"><label>Title</label><input autocomplete="off" id="tracking-title" value="${e(t.title)}" ${editable?'':'disabled'}></div><div class="field"><label>Owner</label><select id="tracking-owner" ${editable?'':'disabled'}>${workOwnerOptions(t.work_kind,t.assignee)}</select></div></div><div class="field"><label>Description (optional)</label><textarea autocomplete="off" id="tracking-description" ${editable?'':'disabled'}>${e(t.description)}</textarea></div>`:dates}<div class="form-row">${field('Blocked / waiting reason','blocked',t.blocked_reason)}${field('Follow-up date','follow-up',t.follow_up_date,'date')}</div>${!simple?`<div class="tracking-owner-grid"><div class="field"><label for="tracking-primary">Primary Owner</label><select id="tracking-primary" ${editable&&(canManage()||me===t.primary_owner)?'':'disabled'}>${workflowMemberOptions('Engineering',t.primary_owner||t.assignee)}</select></div>${collaboratorPicker(t,editable&&(canManage()||me===t.primary_owner))}</div>`:''}${editable?`<button class="btn" data-save-tracking>Save work tracking</button>${simple&&owner?'<button class="btn" data-simple-status>Confirm task status</button>':''}`:''}${!simple&&writable&&(canDev()||canQA())&&d.stage_changes?.[0]&&!d.stage_changes[0].undone&&d.stage_changes[0].to_revision===t.workflow_revision?'<button class="btn" data-undo-stage>Undo Stage Change</button>':''}${d.stage_changes?.length?`<details><summary>Stage change history</summary>${d.stage_changes.map(h=>{const before=JSON.parse(h.before_json),after=JSON.parse(h.after_json);return `<p class="muted-note">${e(timeFmt(h.recorded_at))}: ${e(before.development_status)} → ${e(after.development_status)} · QA ${e(before.qa_status)} → ${e(after.qa_status)}${h.undone?` · Undone by ${e(who(h.undo_actor))}: ${e(h.undo_reason)}`:''}</p>`;}).join('')}</details>`:''}${d.qa_rounds?.length?`<details><summary>QA round history</summary>${d.qa_rounds.map(q=>`<p class="muted-note">Entered ${e(timeFmt(q.entered_at))} · Engineering estimate ${e(dateFmt(q.engineering_due))} · QA due ${e(dateFmt(q.due_date))} · ${e(q.result||'Awaiting test')} ${e(dateFmt(q.completed_date))}${q.is_undone?' · Undone':''}</p>`).join('')}</details>`:''}</section>${!simple?`<section class="tracking-section"><h3 class="card-title">Collaboration</h3>${(d.collaborator_work||[]).map(c=>`<p>${e(who(c.email))} · ${e(c.status)} · ${e(c.description)}</p>`).join('')}${writable&&owner&&collaborators.length?`<div class="form-row"><div class="field"><label>Collaborator</label><select id="collaboration-owner">${collaborators.map(email=>`<option value="${e(email)}">${e(who(email))}</option>`).join('')}</select></div><div class="field"><label>Assistance needed</label><input autocomplete="off" id="collaboration-description"></div><div class="field"><label>Status</label><select id="collaboration-status">${option(['Open','Completed'],'Open')}</select></div></div><button class="btn" data-save-collaboration>Save assigned assistance</button>`:''}</section>`:''}`;
}
function discussionActionControls(d){return `<section class="tracking-section"><h3 class="card-title">Discussion requests</h3>${(d.discussion_actions||[]).map(a=>`<p>${e(who(a.owner_email))} · ${e(a.body)} · ${a.resolved?'Resolved':`Awaiting response ${canWrite()&&(a.owner_email===state.user.email||canManage())?`<button class="account-link" data-resolve-discussion="${e(a.id)}">Resolved</button>`:''}`}</p>`).join('')||'<p class="muted-note">No explicit requests.</p>'}</section>`;}
function discussionRecipientPicker(){return `<div class="field"><label>Response needed from (optional)</label><select id="comment-action-owners" aria-label="Response needed from" multiple>${state.users.filter(u=>memberCanWork(u)&&u.email!==state.user.email).map(u=>`<option value="${e(u.email)}">${e(who(u.email))}</option>`).join('')}</select></div>`;}
function sharedActivityTimeline(d,writable){return d.activities.map(a=>`<div class="timeline-item"><strong>${e(who(a.actor_email))} · ${e(a.action_type)} · ${e(dateFmt(a.activity_date))}</strong><p class="work-notes">${e(a.notes)}</p><p class="muted-note">${e(a.result)}${a.excluded?' · Undone stage change; excluded from workload':''}</p>${attachmentTiles(d.attachments.filter(f=>f.activity_id===a.id),false)}${writable&&!a.comment_id&&(a.actor_email===state.user.email||canManage())?`<button class="account-link" data-edit-shared-activity="${e(a.id)}">Edit activity</button>`:''}${a.edit_history?.length?`<details><summary>Edit history</summary><p class="tracking-history">Original: ${e(a.original_notes)}</p>${a.edit_history.map(h=>`<p class="tracking-history">${e(timeFmt(h.recorded_at))} · ${e(who(h.actor_email))} · ${e(h.activity_date)}<br>${e(h.notes)}</p>`).join('')}</details>`:''}</div>`).join('');}
function pmCanEdit(t){return canWrite()&&(canManage()||state.user.email===(t.pm_owner||t.assignee));}
function pmSourceDetails(d,writable){
 const t=d.task;if(!t.pm_owner)return '';
 return `<details class="task-secondary pm-source-details"><summary>PM source · ${e(who(t.pm_owner))}</summary><p class="muted-note">${ui('This Engineering task was handed off from PM. Its original design and handoff history stay with the same task.')}</p><span class="pm-category">${e(t.work_category)}</span><h4>Design / details</h4><p class="work-notes">${e(t.pm_solution)}</p><details><summary>Handoff & design history</summary>${(d.pm_handoffs||[]).map(h=>`<div class="timeline-item"><strong>${e(h.from_stage)} → ${e(h.to_stage)}</strong><p class="muted-note">${e(who(h.actor_email))} · ${e(timeFmt(h.recorded_at))}</p><p class="work-notes">${e(h.notes)}</p>${h.action==='save'?`<p class="work-notes">${e(h.solution)}</p>`:''}</div>`).join('')}</details></details>`;
}
function pmDesignReadiness(d){
 const t=d.task,request=(d.pm_handoffs||[]).find(h=>h.action==='request-details');
 const requirement=!!(String(t.description||'').trim()||String(t.title||'').trim()),design=!!String(t.pm_solution||'').trim();
 const detailsUpdated=t.pm_stage!=='Needs Details'||!request||String(t.pm_solution||'').trim()!==String(request.solution||'').trim();
 return {requirement,design,detailsUpdated,ready:requirement&&design&&detailsUpdated,request};
}
function pmReadinessList(d){const r=pmDesignReadiness(d),needs=d.task.pm_stage==='Needs Details';
 return `<ul class="pm-readiness-list" aria-label="Design readiness"><li class="${r.requirement?'is-complete':'is-missing'}"><span aria-hidden="true">${r.requirement?'✓':'○'}</span><span>${ui('Requirement recorded')}</span><small>${ui(r.requirement?'Saved':'Add a requirement')}</small></li><li class="${r.design?'is-complete':'is-missing'}"><span aria-hidden="true">${r.design?'✓':'○'}</span><span>${ui('Design details recorded')}</span><small>${ui(r.design?'Saved':'Add design details')}</small></li>${needs?`<li class="${r.detailsUpdated?'is-complete':'is-missing'}"><span aria-hidden="true">${r.detailsUpdated?'✓':'○'}</span><span>${ui('Requested details updated')}</span><small>${ui(r.detailsUpdated?'Saved':'Update the design')}</small></li>`:''}</ul>`;
}
function pmWorkflowCard(d,writable){
 const t=d.task,stage=t.pm_stage||'Draft',pm=t.pm_owner||t.assignee,owner=pmCanEdit(t),active=t.planning_status==='Active',r=pmDesignReadiness(d),current=stage==='Draft'||stage==='Needs Details'?0:stage==='Design Ready'?1:2;
 const labels=['Design','Ready for handoff','Engineering Task'],hints=['Record & review','Choose an engineer','Continue in Engineering'];
 const titles={Draft:'Prepare the design','Design Ready':'Design ready to hand off','Engineer Review':'Waiting for requirement confirmation','Needs Details':r.detailsUpdated?'Details updated — ready to resubmit':'Add the requested details',Implementation:'Engineering is underway',Completed:'Task completed'};
 const descriptions={Draft:'Save your idea and proposed design. Review the scope, key behavior and acceptance details before marking the design ready.','Design Ready':'Choose an engineer and submit Handoff. This same task then opens as an ordinary Engineering task.','Engineer Review':'The engineer reviews your design, confirms the requirement, or asks PM to add details.','Needs Details':r.detailsUpdated?'Review the updated design, then submit Handoff to return the next action to the engineer.':'Use Edit PM task to add the requested details to the design. Save them, then submit Handoff again.',Implementation:'Requirement confirmed. Continue the Engineering workflow below.',Completed:'The task is complete. Its design, handoffs and activity remain available below.'};
 const latest=d.pm_handoffs?.[0],revised=stage==='Draft'&&latest?.action==='save'&&latest.from_stage==='Design Ready';
 let actions='';if(active&&!t.archived){
  if(owner&&stage==='Draft')actions=`${!r.ready?'<button class="btn primary" data-edit-pm data-pm-edit-focus="design">Add design details</button>':''}<button class="btn ${r.ready?'primary':''}" data-pm-action="design-ready" ${r.ready?'':'disabled'}>Mark design ready <span aria-hidden="true">→</span></button>${r.ready?'<button class="account-link" data-edit-pm data-pm-edit-focus="design">Edit design</button>':''}`;
  if(owner&&stage==='Design Ready')actions='<button class="btn primary" data-pm-action="handoff">Choose engineer & hand off <span aria-hidden="true">→</span></button><button class="account-link" data-pm-action="revise-design">Back to Draft</button>';
  if(owner&&stage==='Needs Details')actions=`${!r.detailsUpdated||!r.design?'<button class="btn primary" data-edit-pm data-pm-edit-focus="design">Add requested details</button>':''}<button class="btn ${r.ready?'primary':''}" data-pm-action="handoff" ${r.ready?'':'disabled'}>Resubmit Handoff <span aria-hidden="true">→</span></button>`;
 }
 const nextOwner=['Engineer Review'].includes(stage)?t.pm_engineer:stage==='Implementation'?d.workflow.owner:stage==='Completed'?'':pm;
 return `<section class="pm-workflow-card pm-workflow-guided" data-pm-stage="${e(stage)}"><div class="pm-workflow-head"><h3 class="card-title">PM workflow</h3>${badge(stage)}</div><ol class="pm-steps" aria-label="PM handoff progress">${labels.map((label,i)=>`<li class="${stage==='Completed'||i<current?'is-done':i===current?'is-current':''}" ${stage!=='Completed'&&i===current?'aria-current="step"':''}><span class="pm-step-marker">${stage==='Completed'||i<current?'✓':i+1}</span><div><strong>${label}</strong><small>${ui(hints[i])}</small></div></li>`).join('')}</ol><div class="pm-stage-guidance" role="status"><span class="pm-stage-symbol" aria-hidden="true">${stage==='Design Ready'||stage==='Completed'?'✓':stage==='Needs Details'?'!':stage==='Engineer Review'?'→':'✎'}</span><div><h4>${ui(titles[stage]||titles.Draft)}</h4><p>${ui(descriptions[stage]||descriptions.Draft)}</p></div></div>${revised?`<p class="pm-revision-note">${ui('The ready design was changed. Review the updated version and mark it ready again.')}</p>`:''}${stage==='Draft'||stage==='Needs Details'?pmReadinessList(d):''}${stage==='Needs Details'&&r.request?`<div class="pm-question"><strong>@${e(who(pm))} · Details needed</strong><p class="work-notes">${e(r.request.notes)}</p></div>`:''}${!active&&!t.archived&&stage!=='Completed'?`<p class="pm-revision-note">${ui('Set Planning status to Active in Work tracking when you are ready to continue.')}</p>`:''}<div class="pm-action-footer"><div class="pm-action-owner">${nextOwner?`${avatarHtml(nextOwner)}<span><small>${ui(stage==='Design Ready'?'Handoff owner':'Next action owner')}</small><strong>${e(who(nextOwner))}</strong></span>`:`<span>${ui('No further action needed.')}</span>`}</div>${actions?`<div class="pm-workflow-actions">${actions}</div>`:''}${!owner&&['Draft','Design Ready','Needs Details'].includes(stage)&&active&&!t.archived?`<p class="pm-waiting-note">${ui('Waiting for {owner} to continue.',{owner:who(pm)})}</p>`:''}</div></section>`;
}
function renderPmDetail(d){
 state.detailData=d;const t=d.task,writable=canWrite()&&!t.archived,edit=pmCanEdit(t),record=writable&&edit,related=d.links||[];
 $('#detail-content').innerHTML=`<div class="panel-header"><span class="panel-kicker">PM Task ${t.archived?badge('Archived'):''}</span><button class="close" data-close="detail" aria-label="Close task">×</button></div><div class="panel-body task-focus"><div class="pm-title-row"><h2 class="detail-heading">${e(t.title)}</h2><span>${badge(t.priority)}</span></div>${instructionFor('pm-task')}${pmWorkflowCard(d,writable)}<section class="pm-design-card"><div class="pm-workflow-head"><h3 class="card-title">Requirement & design</h3>${edit&&!t.archived?'<button class="btn tiny" data-edit-pm>Edit PM task</button>':''}</div><span class="pm-category">${e(t.work_category)}</span><h4>Requirement / idea</h4><p class="work-notes">${e(t.description)||ui('Add the requirement, problem and intended outcome.')}</p><h4>Design / details</h4><p class="work-notes">${e(t.pm_solution)||ui('Record the proposed design and acceptance details before Handoff.')}</p></section><section class="tracking-section"><h3 class="card-title">Work tracking</h3><div class="form-row"><div class="field"><label>Planning status</label><select id="tracking-planning" ${edit&&!t.archived?'':'disabled'}>${option(['Backlog','Planned','Active',...(t.pm_stage==='Completed'?['Completed']:[])],t.planning_status)}</select></div><div class="field"><label>Follow-up date</label><input autocomplete="off" id="tracking-follow-up" type="date" value="${e(t.follow_up_date)}" ${edit&&!t.archived?'':'disabled'}></div></div><div class="field"><label>Blocked / waiting reason</label><input autocomplete="off" id="tracking-blocked" value="${e(t.blocked_reason)}" ${edit&&!t.archived?'':'disabled'}></div>${edit&&!t.archived?'<button class="btn" data-save-tracking>Save work tracking</button>':''}</section><section class="task-evidence"><div class="evidence-head"><h3>Task images & files</h3>${writable?'<input autocomplete="off" type="file" id="task-files" multiple hidden>':''}</div><div class="screenshot-grid">${attachmentTiles(d.attachments.filter(f=>!f.activity_id&&!f.comment_id),writable)||ui('No images added yet.')}</div>${writable?`<button type="button" class="task-drop-zone" id="task-drop-zone" aria-label="Add task images or files: drop, paste, or click to choose files">${ui('Drop images or files here, click to choose, or paste screenshots with Ctrl/Cmd + V')}</button>`:''}</section>${record?`<section class="tracking-section"><h3 class="card-title">Add activity</h3><div class="field"><label>Work notes</label><textarea autocomplete="off" id="activity-notes"></textarea></div><input autocomplete="off" id="activity-result" type="hidden" value=""><select data-key="activity-action" hidden><option value="Other">Other</option></select><select id="activity-env" hidden><option value="${e(t.current_environment)}">${e(t.current_environment)}</option></select><div class="form-row"><div class="field"><label>Work date</label><input autocomplete="off" id="activity-date" type="date" value="${state.day}"></div><div class="field"><label>Work role</label><select id="activity-role">${option([...new Set([...(state.user.groups||[]).filter(g=>g!=='Management'),...(canManage()?['PM','Engineering','QA']:[])])],state.user.email===t.pm_owner?'PM':canDev()?'Engineering':'QA')}</select></div></div>${evidencePicker('activity-files','activity','Attachments (optional)')}<button class="btn primary" id="add-activity">Save activity</button></section>`:''}<details class="task-secondary"><summary>Activity timeline</summary>${sharedActivityTimeline(d,writable)}</details><details class="task-secondary"><summary>Handoff & design history</summary>${(d.pm_handoffs||[]).map(h=>`<div class="timeline-item"><strong>${e(h.from_stage)} → ${e(h.to_stage)}</strong><p class="muted-note">${e(who(h.actor_email))} · ${e(timeFmt(h.recorded_at))}</p><p class="work-notes">${e(h.notes)}</p>${h.action==='save'?`<details><summary>Design version</summary><p class="work-notes">${e(h.solution)}</p></details>`:''}</div>`).join('')||ui('No handoffs yet.')}</details><details class="task-secondary" id="task-discussion"><summary>Discussion</summary>${d.comments.map(c=>`<div class="comment-box"><strong>${e(who(c.actor_email))}</strong>${commentReplyLink(c,d)}<p class="work-notes">${e(c.body)}</p>${attachmentTiles(d.attachments.filter(a=>a.comment_id===c.id),writable)}${writable?`<button class="account-link" data-reply-comment="${e(c.id)}">Reply</button>`:''}</div>`).join('')}${discussionActionControls(d)}${writable?`<div id="discussion-compose-anchor"><div class="reply" id="comment-composer"><div id="comment-reply-context" hidden></div><textarea autocomplete="off" id="comment-body"></textarea>${discussionRecipientPicker()}${evidencePicker('comment-files','comment','Images for this comment')}<button class="btn" id="add-comment">Post comment</button></div></div>`:''}</details>${related.length?`<details class="task-secondary"><summary>Related Engineering work</summary>${related.map(l=>`<p><button class="account-link" data-open="${e(l.engineering_task_id)}">${e(state.tasks.find(x=>x.id===l.engineering_task_id)?.title||'Engineering task')}</button></p>`).join('')}</details>`:''}${edit?`<section class="task-secondary task-manage" aria-label="Task actions"><div class="task-action-options"><button class="btn" id="${t.archived?'restore-task':'archive-task'}">${t.archived?'Restore task':'Archive task'}</button>${!t.archived?'<button class="btn danger-link" id="remove-task">Delete task</button>':''}</div><p class="muted-note">${ui('Archive preserves history and can be restored. Tasks with shared work or released-version history are archived when removed.')}</p></section>`:''}</div>`;
 captureTaskDraftBaseline();syncWorkflowStage();updateProfileAvatars();if(state.replyTo)startCommentReply(state.replyTo,false);
}
function editPmTask(focusDesign=false){const t=state.detailData.task;if(!pmCanEdit(t)||t.archived)return;
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>Edit PM task</h2><button class="close" data-close="modal">×</button></div><p class="pm-editor-guidance">${ui(t.pm_stage==='Needs Details'?'Add the requested details here. Saving keeps the task with PM until you resubmit Handoff.':t.pm_stage==='Design Ready'?'Changes to the requirement or design return this task to Draft. Save the changes, then review and mark the updated design ready again.':t.pm_stage==='Draft'?'Save your draft as you work. When the design is finished, use Mark design ready in PM workflow.':'Updates are saved with this task. Use the current workflow action to continue.')}</p><div class="field"><label for="pm-edit-title">Title</label><input autocomplete="off" id="pm-edit-title" maxlength="160" value="${e(t.title)}"></div><div class="form-row"><div class="field"><label for="pm-edit-owner">PM owner</label><select id="pm-edit-owner">${workflowMemberOptions('PM',t.pm_owner||t.assignee)}</select></div><div class="field"><label for="pm-edit-category">PM work category</label><select id="pm-edit-category">${option(pmCategories,t.work_category)}</select></div></div><div class="field"><label for="pm-edit-requirement">Requirement / idea</label><textarea autocomplete="off" id="pm-edit-requirement">${e(t.description)}</textarea></div><div class="field"><label for="pm-edit-solution">Design / details</label><textarea autocomplete="off" id="pm-edit-solution" class="pm-design-input" placeholder="${e(tr('Describe the proposed solution, key behavior and acceptance details.'))}" data-ui-placeholder="Describe the proposed solution, key behavior and acceptance details.">${e(t.pm_solution)}</textarea></div><p id="pm-edit-error" role="alert"></p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="pm-save-design">${t.pm_stage==='Draft'?'Save draft':t.pm_stage==='Needs Details'?'Save details':'Save changes'}</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#pm-save-design').onclick=()=>busy(async()=>{const button=$('#pm-save-design');button.disabled=true;try{await api('/tasks/'+t.id+'/pm-workflow',{method:'POST',body:JSON.stringify({action:'save',confirm:true,expected_revision:t.workflow_revision,title:$('#pm-edit-title').value,pm_owner:$('#pm-edit-owner').value,work_category:$('#pm-edit-category').value,description:$('#pm-edit-requirement').value,solution:$('#pm-edit-solution').value,activity_date:state.day})});closeModal();await reload();if(['Draft','Design Ready','Needs Details'].includes(t.pm_stage))$('#detail-panel').scrollTop=0;showToast(t.pm_stage==='Design Ready'&&state.detailData.task.pm_stage==='Draft'?'Design changed. Review it again and mark it ready.':t.pm_stage==='Needs Details'?'Details saved. Review them and resubmit Handoff.':t.pm_stage==='Draft'?'Draft saved. Review the design and mark it ready when finished.':'PM task updated.');}catch(error){$('#pm-edit-error').textContent=error.message;button.disabled=false;}});
 if(focusDesign)$('#pm-edit-solution').focus();
}
function confirmPmAction(action){const t=state.detailData.task,d=state.detailData,r=pmDesignReadiness(d),labels={'design-ready':'Review design readiness',handoff:t.pm_stage==='Needs Details'?'Resubmit Handoff':'Hand off to Engineering',accept:'Confirm requirement','request-details':'Return to PM','revise-design':'Back to Draft'};
 const description={'design-ready':'Review your saved design below. Marking it ready opens the handoff step, where you choose an engineer and submit it.',handoff:'Confirm the engineer and saved design. Handoff switches this record to an ordinary Engineering task and assigns it to that engineer.',accept:'Continue the existing Engineering workflow within this task.','request-details':'Describe the missing details, feasibility concern or design change needed. This same task returns to PM; PM receives an @ request and the next action.','revise-design':'Return the design to Draft to continue editing.'};
 if(action==='design-ready'&&!r.ready){editPmTask(true);return;}
 const files=d.attachments.filter(f=>!f.activity_id&&!f.comment_id),confirmLabels={'design-ready':'Mark design ready',handoff:t.pm_stage==='Needs Details'?'Resubmit Handoff':'Submit Handoff',accept:'Confirm requirement','request-details':'Send to PM','revise-design':'Back to Draft'};
 const review=action==='design-ready'?`<section class="pm-design-review"><div class="pm-review-label">Requirement / idea</div><p class="work-notes">${e(t.description||t.title)}</p><div class="pm-review-label">Design / details</div><p class="work-notes">${e(t.pm_solution)}</p><div class="pm-review-files">${ui('{count} reference files attached.',{count:files.length})}</div></section><p class="pm-review-prompt">${ui('Check that the scope, key behavior and acceptance details are clear enough for the engineer to review.')}</p><div class="pm-confirm-next"><strong>Design Ready</strong><span aria-hidden="true">→</span><span>${ui('Choose an engineer & submit Handoff')}</span></div>`:'';
 trackingConfirmation(labels[action],`<p>${ui(description[action])}</p>${review}${action==='handoff'?`<div class="field"><label for="pm-handoff-engineer">Engineer</label><select id="pm-handoff-engineer" ${t.pm_resume_stage==='Implementation'?'disabled':''}>${workflowMemberOptions('Engineering',t.pm_engineer)}</select><p class="muted-note">${ui('This engineer receives the next action and reviews the requirement before implementation.')}</p></div><div class="pm-confirm-next"><strong>Engineer Review</strong><span aria-hidden="true">→</span><span>${ui('Continue in the ordinary Engineering Next Step')}</span></div>`:''}${['handoff','request-details'].includes(action)?`<div class="field"><label for="pm-handoff-notes">${action==='request-details'?'Details needed':'Handoff notes (optional)'}</label><textarea autocomplete="off" id="pm-handoff-notes"></textarea></div>`:''}`,()=>api('/tasks/'+t.id+'/pm-workflow',{method:'POST',body:JSON.stringify({action,confirm:true,expected_revision:t.workflow_revision,engineer:$('#pm-handoff-engineer')?.value,notes:$('#pm-handoff-notes')?.value||'',activity_date:state.day})}),{label:confirmLabels[action],onSuccess:()=>{if(action==='design-ready'){$('#detail-panel').scrollTop=0;showToast('Design ready. Choose an engineer and submit Handoff.');document.querySelector('[data-pm-action="handoff"]')?.focus({preventScroll:true});}if(action==='handoff'){$('#detail-panel').scrollTop=0;showToast('Handoff submitted. This task is now in Engineering.');}}});
}
document.addEventListener('click',ev=>{const edit=ev.target.closest('[data-edit-pm]');if(edit)return editPmTask(!!edit.dataset.pmEditFocus);const action=ev.target.closest('[data-pm-action]');if(action)return confirmPmAction(action.dataset.pmAction);});

function renderSimpleDetail(d){state.detailData=d;const t=d.task,writable=canWrite()&&!t.archived;
 $('#detail-content').innerHTML=`<div class="panel-header"><span class="panel-kicker">${e(t.work_kind)}</span><button class="close" data-close="detail">×</button></div><div class="panel-body task-focus"><h2>${e(t.title)}</h2>${instructionFor('simple-work')}<p>${e(who(t.assignee))} · ${badge(t.work_status)} · ${badge(t.planning_status)}</p><p class="work-notes">${e(t.description)}</p>${trackingOverview(d,writable)}${writable?`<section class="tracking-section"><h3 class="card-title">Add activity</h3><div class="field"><label>Work notes</label><textarea autocomplete="off" id="activity-notes"></textarea></div><input autocomplete="off" id="activity-result" type="hidden" value=""><select data-key="activity-action" hidden><option value="Other">Other</option></select><select id="activity-env" hidden><option value="—">—</option></select><div class="form-row"><div class="field"><label>Work date</label><input autocomplete="off" id="activity-date" type="date" value="${state.day}"></div><div class="field"><label>Work role</label><select id="activity-role">${option(t.work_kind==='PM Task'?['PM']:['Other',...(state.user.groups||[]).filter(g=>g!=='Management')],t.work_kind==='PM Task'?'PM':'Other')}</select></div></div>${evidencePicker('activity-files','activity','Attachments (optional)')}<button class="btn primary" id="add-activity">Save activity</button></section>`:''}<details class="task-secondary"><summary>Activity timeline</summary>${sharedActivityTimeline(d,writable)}</details><section class="tracking-section"><h3 class="card-title">Task attachments</h3>${attachmentTiles(d.attachments.filter(f=>!f.activity_id&&!f.comment_id),writable)}</section><details class="task-secondary" id="task-discussion"><summary>Discussion</summary>${d.comments.map(c=>`<div class="comment-box"><strong>${e(who(c.actor_email))}</strong>${commentReplyLink(c,d)}<p>${e(c.body)}</p>${writable?`<button class="account-link" data-reply-comment="${e(c.id)}">Reply</button>`:''}</div>`).join('')}${discussionActionControls(d)}${writable?`<div id="discussion-compose-anchor"><div class="reply" id="comment-composer"><div id="comment-reply-context" hidden></div><textarea autocomplete="off" id="comment-body"></textarea>${discussionRecipientPicker()}${evidencePicker('comment-files','comment','Attachments (optional)')}<button class="btn" id="add-comment">Post comment</button></div></div>`:''}</details></div>`;
 updateProfileAvatars();
}
function dashboardWaitingStep(t){
 const phase=t.workflow?.phase;
 if(t.work_kind==='PM Task'&&phase==='pm')return {label:t.pm_stage,tone:t.pm_stage==='Needs Details'?'red':'amber'};
 if(t.work_kind==='Quick Task')return {label:t.work_status||'To Do',tone:t.work_status==='Completed'?'green':'amber'};
 if(phase==='review')return {label:t.feasibility==='Needs Clarification'?'Clarify requirements':t.feasibility==='Cannot Complete'?'Review scope':'Engineer review',tone:t.feasibility==='Cannot Complete'?'red':'amber'};
 if(phase==='qa')return {label:t.qa_status==='Retest Required'?'QA retest':'QA testing',tone:'amber'};
 if(phase==='production')return {label:'Production deploy',tone:'amber'};
 if(phase==='done')return {label:t.development_status==='Closed'?'Completed':'Completion check',tone:t.development_status==='Closed'?'green':'amber'};
 if(phase==='development')return {label:t.qa_status&&t.qa_status!=='Not Tested'?'QA changes':t.development_status==='Merged / Awaiting Stage'?'Stage deploy':'Development',tone:t.qa_status&&t.qa_status!=='Not Tested'?'red':'amber'};
 return {label:t.planning_status||'Pending',tone:'gray'};
}
function dashboardQueueRow(t,{owner='',preview='',meta='',label='',tone='gray',extraStatus=''}={}){
 const tid=t.task_id||t.id;
 return `<div role="listitem"><button type="button" class="dashboard-queue-row" data-open="${e(tid)}" aria-label="Open ${e(t.title)}"><span class="queue-task"><span class="queue-title">${e(t.title)}</span>${preview?`<span class="queue-preview">${e(preview)}</span>`:meta?`<span class="queue-meta">${e(meta)}</span>`:''}</span><span class="queue-owner" title="${e(who(owner))}">${owner?avatarHtml(owner,'queue-avatar'):''}<span class="queue-owner-name">${e(owner?who(owner):'Unassigned')}</span></span><span class="queue-status"><span class="badge ${e(tone)}">${e(label)}</span>${extraStatus?badge(extraStatus):''}</span><svg class="queue-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="m6 4 4 4-4 4"/></svg></button></div>`;
}
function dashboardQueue(title,items,render,{actionLabel='Next step',emptyText='No items.'}={}){
 return `<section class="dashboard-queue" aria-label="${e(title)}"><div class="queue-heading"><h2>${e(title)}</h2><span class="queue-count" aria-label="${items.length} items">${items.length}</span></div>${items.length?`<div class="queue-column-head" aria-hidden="true"><span>Task</span><span>Owner</span><span>${e(actionLabel)}</span><span></span></div><div class="queue-rows" role="list">${items.map(render).join('')}</div>`:`<div class="queue-empty">${ui(emptyText)}</div>`}</section>`;
}
function dashboardTracking(s){
 const requests=[...(s.discussion_actions||[]).map(a=>({...a,kind:'Discussion'})),...(s.collaborator_actions||[]).map(a=>({...a,kind:'Collaboration'}))];
 const requestList=dashboardQueue('Discussion & collaboration',requests,a=>dashboardQueueRow(a,{owner:a.owner_email||a.email||state.user.email,preview:a.body||a.description,label:a.kind==='Discussion'?'Reply needed':'Assigned assistance',tone:'amber'}),{actionLabel:'Action',emptyText:'No requests need your response.'});
 const waiting=dashboardQueue('Waiting on Others',s.waiting_on_others||[],t=>{const step=dashboardWaitingStep(t);return dashboardQueueRow(t,{owner:t.workflow?.owner||t.assignee,meta:[t.work_kind&&t.work_kind!=='Engineering'?t.work_kind:t.type,t.category&&t.category!=='General'?t.category:''].filter(Boolean).join(' · '),...step});},{actionLabel:'Waiting for',emptyText:'No related tasks are waiting on someone else.'});
 const followUp=dashboardQueue('Needs Follow-up',s.needs_follow_up||[],t=>{const f=t.follow_up;return dashboardQueueRow(t,{owner:t.workflow?.owner||t.assignee,preview:f.reason||tr('{days} days without progress',{days:f.days}),label:f.status,tone:/Stale|Overdue|Blocked/.test(f.status)?'red':'amber',extraStatus:f.overdue&&f.status!=='Overdue'?'Overdue':''});},{actionLabel:'Attention',emptyText:'No tasks need follow-up.'});
 return requestList+waiting+followUp+``;
}
function workloadShell(){return `<section class="workload-panel"><div class="workload-heading"><h2 class="card-title">Workload</h2><span>${e(dateFmt(state.day))}</span></div><div id="workload-results" aria-live="polite">${ui('Loading activity…')}</div></section>`;}
function workloadModel(data){
 const groups=new Map();let activities=0,returns=0;
 for(const r of [...(data.shared||[]).map(r=>({...r,source:'shared'})),...(data.daily||[]).map(r=>({...r,source:'daily'}))]){
  const label=r.source==='daily'?'Daily Work':r.work_role==='QA'?'QA':r.work_role==='Engineering'?'Engineering':r.work_role==='PM'?'PM':r.work_kind==='Quick Task'?'Quick Tasks':'Shared work';
  const key=JSON.stringify([r.email,label]),count=Number(r.activity_count)||0,rework=Number(r.rework_requests)||0;
  const group=groups.get(key)||{email:r.email,label,categories:new Set(),activities:0,returns:0};group.activities+=count;group.returns+=rework;if(r.category)group.categories.add(r.category);groups.set(key,group);activities+=count;returns+=rework;
 }
 return {activities,returns,rows:[...groups.values()].map(r=>({...r,categories:[...r.categories].sort()})).sort((a,b)=>a.email.localeCompare(b.email)||a.label.localeCompare(b.label))};
}
async function loadWorkload(){const root=$('#workload-results');if(!root)return;const data=await api('/workload?date='+state.day);if(!root.isConnected)return;const model=workloadModel(data),team=isBoss();
 root.innerHTML=`<div class="workload-summary"><div><strong>${model.activities}</strong><span>Activities</span></div><div><strong>${model.returns}</strong><span>QA returns</span></div></div>${model.rows.length?`<div class="workload-columns" aria-hidden="true"><span>${team?'Person / Work':'Work'}</span><span>Activities</span><span>QA returns</span></div><div class="workload-list" role="list">${model.rows.map(r=>`<div class="workload-row" role="listitem"><div class="workload-work">${team?avatarHtml(r.email):''}<div>${team?`<span class="workload-person">${e(who(r.email))}</span>`:''}<strong>${e(r.label)}</strong><span class="workload-categories" title="${e(r.categories.join(' · '))}">${e(r.categories.join(' · '))}</span></div></div><span class="workload-value" aria-label="${r.activities} activities">${r.activities}</span><span class="workload-value ${r.returns?'has-returns':''}" aria-label="${r.returns} QA returns">${r.returns||'—'}</span></div>`).join('')}</div>`:`<p class="workload-empty">${ui('No work recorded for this date.')}</p>`}`;updateProfileAvatars();
}
async function openDashboardActivity(tid,aid){
 if(hasDirtyTask())return askDiscardTask(()=>{closeDetail(true);return openDashboardActivity(tid,aid)});
 const viewer=state.user.email,perspective=state.workspaceMode,d=await api('/tasks/'+tid);if(state.user?.email!==viewer||state.workspaceMode!==perspective)return;const a=d.activities.find(x=>x.id===aid);if(!a)return openDetail(tid);
 const files=d.attachments.filter(f=>f.activity_id===aid||(a.comment_id&&f.comment_id===a.comment_id)||(a.result==='New request submitted'&&!f.activity_id&&!f.comment_id));
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>Activity details</h2><button class="close" data-close="modal" aria-label="Close activity">×</button></div><h3 class="activity-detail-title">${e(d.task.title)}</h3><div class="activity-detail-meta">${avatarHtml(a.actor_email)}<span>${e(who(a.actor_email))}</span><span>${e(dateFmt(a.activity_date))}</span></div><div class="workspace-tag-row">${badge(a.action_type)}${a.result?badge(a.result):''}</div><p class="activity-detail-notes">${e(a.notes)}</p>${attachmentTiles(files,false)}<div class="form-actions"><button class="btn" id="activity-open-task">Open task</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#activity-open-task').onclick=()=>{closeModal();busy(()=>openDetail(tid))};
}
async function editSharedActivity(aid){const d=state.detailData,a=d.activities.find(x=>x.id===aid);if(!a)return;pendingActivityFiles=[];
 $('#modal-content').innerHTML=`<div id="shared-activity-editor"><div class="modal-head"><h2>Edit activity</h2><button class="close" data-close="modal">×</button></div><div class="field"><label>Work notes</label><textarea autocomplete="off" id="edit-activity-notes">${e(a.notes)}</textarea></div><div class="form-row"><div class="field"><label>Work date</label><input autocomplete="off" type="date" id="edit-activity-date" value="${e(a.activity_date)}"></div></div>${attachmentTiles(d.attachments.filter(f=>f.activity_id===aid),true)}${evidencePicker('edit-activity-files','activity','Attachments (optional)')}<p id="activity-edit-error" role="alert"></p><button class="btn primary" id="save-activity-edit">Save changes</button></div>`;$('#modal-shade').classList.remove('hidden');
 $('#edit-activity-files').onchange=ev=>queueEvidence([...ev.target.files],'activity');
 $('#save-activity-edit').onclick=()=>busy(async()=>{const b=$('#save-activity-edit');b.disabled=true;try{await api('/tasks/'+d.task.id+'/activity-edit',{method:'POST',body:JSON.stringify({activity_id:aid,notes:$('#edit-activity-notes').value,activity_date:$('#edit-activity-date').value})});await uploadTaskFiles(pendingActivityFiles,{activityId:aid});pendingActivityFiles=[];closeModal();await reload();}catch(error){$('#activity-edit-error').textContent=error.message;b.disabled=false;}});
}
function syncNewWorkKind(){const kind=$('#new-work-kind')?.value||'Engineering';for(const key of ['new-type','new-priority']){const control=document.querySelector('[data-key="'+key+'"]');if(control)control.closest('.field').hidden=kind!=='Engineering';}if($('#new-category'))$('#new-category').closest('.field').hidden=kind!=='Engineering';if($('#new-parent'))$('#new-parent').closest('.field').hidden=kind!=='Engineering';const intro=$('#modal-content .task-create-intro');if(intro)systemText(intro,kind==='Engineering'?'Describe the request, choose an engineer, and add the details they need to review it.':kind==='PM Task'?'Record the requirement and design. Complete the design, then hand it to an engineer for confirmation.':'Independent small work uses a task. Work that belongs to an existing task should be added as Activity.');const helper=$('#new-parent')?.closest('.task-create-section')?.querySelector('.muted-note');if(helper)helper.hidden=kind!=='Engineering';if($('#new-assignee'))$('#new-assignee').innerHTML=workOwnerOptions(kind);if($('#new-work-category'))$('#new-work-category').closest('.field').hidden=kind!=='PM Task';}
document.addEventListener('change',ev=>{if(ev.target.id==='new-work-kind')syncNewWorkKind();});
document.addEventListener('click',ev=>{const edit=ev.target.closest('[data-edit-shared-activity]');if(edit)return busy(()=>editSharedActivity(edit.dataset.editSharedActivity));const resolve=ev.target.closest('[data-resolve-discussion]');if(resolve)return busy(async()=>{await api('/discussion-actions/'+resolve.dataset.resolveDiscussion+'/resolve',{method:'POST',body:'{}'});await reload();});const t=state.detailData?.task;if(!t)return;
 if(ev.target.closest('[data-save-tracking]'))return busy(async()=>{const d={planning_status:$('#tracking-planning').value,blocked_reason:$('#tracking-blocked').value,follow_up_date:$('#tracking-follow-up').value,expected_revision:t.workflow_revision};if(t.work_kind==='Engineering'||t.work_kind==='PM Task'&&t.pm_stage==='Implementation'){if((canManage()||[t.primary_owner,t.assignee,...JSON.parse(t.collaborators_json||'[]')].includes(state.user.email))&&$('#tracking-delivery').value!==t.estimated_delivery_date)d.estimated_delivery_date=$('#tracking-delivery').value;if(canQA()&&$('#tracking-qa-due').value!==t.qa_due_date)d.qa_due_date=$('#tracking-qa-due').value;if(canManage()||state.user.email===t.primary_owner){d.primary_owner=$('#tracking-primary').value;d.collaborators=[...document.querySelectorAll('[name="tracking-collaborator"]:checked')].map(x=>x.value);}}if(t.work_kind==='Quick Task'){d.title=$('#tracking-title').value;d.description=$('#tracking-description').value;d.assignee=$('#tracking-owner').value;}if(t.work_kind!=='PM Task'&&$('#tracking-category'))d.work_category=$('#tracking-category').value;await api('/tasks/'+t.id+'/tracking',{method:'PATCH',body:JSON.stringify(d)});await reload();showToast('Work tracking saved');});
 if(ev.target.closest('[data-simple-status]'))return trackingConfirmation('Confirm task status',`<p>${e($('#tracking-status').value)}</p>`,()=>api('/tasks/'+t.id+'/work-status',{method:'POST',body:JSON.stringify({status:$('#tracking-status').value,completed_date:$('#tracking-completed').value||todayDate(),expected_revision:t.workflow_revision,confirm:true})}));
 if(ev.target.closest('[data-undo-stage]'))return trackingConfirmation('Undo Stage Change',`<p>${ui('Restore the previous stage without deleting activity. Use the QA result for a formal return to Engineering.')}</p><div class="field"><label>Reason for undo</label><textarea autocomplete="off" id="undo-reason"></textarea></div>`,()=>api('/tasks/'+t.id+'/undo-stage',{method:'POST',body:JSON.stringify({confirm:true,reason:$('#undo-reason').value,expected_revision:t.workflow_revision})}));
 if(ev.target.closest('[data-save-collaboration]'))return busy(async()=>{await api('/tasks/'+t.id+'/collaborator-work',{method:'POST',body:JSON.stringify({email:$('#collaboration-owner').value,description:$('#collaboration-description').value,status:$('#collaboration-status').value})});await reload();});
 if(ev.target.closest('[data-link-engineering]'))return busy(async()=>{await api('/tasks/'+t.id+'/link-engineering',{method:'POST',body:JSON.stringify({engineering_task_id:$('#pm-engineering-link').value})});await reload();});
});
function trackingConfirmation(title,body,action,options={}){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${e(title)}</h2><button class="close" data-close="modal">×</button></div>${body}<p id="tracking-error" role="alert"></p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-tracking">${e(options.label||'Confirm')}</button></div>`;$('#modal-shade').classList.remove('hidden');$('#confirm-tracking').onclick=()=>{const button=$('#confirm-tracking');if(button.disabled)return;button.disabled=true;return busy(async()=>{try{await action();closeModal();await reload();options.onSuccess?.();}catch(error){const message=$('#tracking-error');if(message)message.textContent=error.message;else showToast(error.message,true);button.disabled=false;}});};}

let backgroundSyncBusy=false;
document.addEventListener('input',ev=>{if(ev.target.closest('.tracking-section')&&ev.target.matches('input,textarea,select')&&!ev.target.matches('[data-collaborator-search]'))state.trackingDirty=true;});
document.addEventListener('change',ev=>{if(ev.target.closest('.tracking-section')&&ev.target.matches('input,textarea,select')&&!ev.target.matches('[data-collaborator-search]'))state.trackingDirty=true;if(ev.target.id==='work-kind-filter'){state.workKindFilter=ev.target.value;render();}if(ev.target.id==='planning-filter'){state.planningFilter=ev.target.value;render();}});
async function syncVisibleWorkspace(){if(['releases','team'].includes(state.view))return;if(!state.user||backgroundSyncBusy||document.hidden||!$('#modal-shade').classList.contains('hidden')||hasDirtyTask()||document.activeElement?.matches('input,textarea,select'))return; backgroundSyncBusy=true;try{const position=window.scrollY;if(state.detail){await refreshTaskDetail();}else if(state.privateDetail){await refreshPrivateDetail();}else{await reload();window.scrollTo(0,position);if(state.view==='daily')await loadDaily();} }catch(error){if(error.status===401)await showLogin();}finally{backgroundSyncBusy=false;}}
setInterval(syncVisibleWorkspace,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncVisibleWorkspace();});
